esday.*"}]

[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-WHO-004",
    "category": "Wholesale Accounts",
    "question": "What are your payment terms?",
    "answer": "Terms are Net-15 via automated ACH through the wholesale portal. Invoices generate when the delivery departs. New accounts need credit approval before the first delivery, and balances more than 15 days past due pause deliveries.",
    "escalate_to_human": false
}"}, {"source": "WHOLESALE_ORDERING_GUIDE.md", "quote": "- **Tier 1 – Standard:** Default wholesale pricing for all approved accounts. - **Tier 2 – Volume:** Applies once an account averages **$600.00 or more per week** over a trailing 4-week period. Example: Country Sourdough Boule is $6.25 at Tier 1 and $5.75 at Tier 2 (retail $9.50). - Current price lists live in the B2B Portal and follow `daily_bake_matrix.json`."}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-WHO-002",
    "category": "Wholesale Accounts",
    "question": "What is the minimum order for wholesale delivery?",
    "answer": "The minimum order value is $75.00 per delivery drop. Orders below $75.00 incur a $15.00 small-drop surcharge.",
    "escalate_to_human": false
}"}, {"source": "WHOLESALE_ORDERING_GUIDE.md", "quote": "- **Credit Application:** New accounts submit a credit application and are approved before first delivery. Approval typically takes 3 business days. - **Payment Terms:** Net-15 via automated ACH through the wholesale portal. Invoices generate upon delivery departure. - **Late Payment:** Balances more than 15 days past due pause deliveries. A 1.5% monthly late fee applies after day 30. - **Quality Claims:** Missing, damaged, or unsatisfactory items must be reported within **12 hours of delivery drop** with cross-section photos. Approved claims are credited to the next invoice."}]

[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-RET-002",
    "category": "Daily Retail & Orders",
    "question": "What days are you open?",
    "answer": "We bake and sell Tuesday through Sunday. We are closed on Mondays, which is our rest and fermentation prep day, and there is no retail, delivery, or pickup on Mondays.",
    "escalate_to_human": false
}"}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-WHO-003",
    "category": "Wholesale Accounts",
    "question": "When do you deliver, and which zones do you serve?",
    "answer": "We deliver Tuesday through Sunday between 4:30 AM and 7:00 AM. Zone A (Urban Core) receives daily drops, and Zone B (Outer Metro) receives drops on Tuesday, Thursday, and Saturday.",
    "escalate_to_human": false
}"}, {"source": "WHOLESALE_ORDERING_GUIDE.md", "quote": "- **Minimum Order Value (MOV):** $75.00 per delivery drop. Orders below $75.00 incur a $15.00 small-drop surcharge. - **Delivery Schedule:** Tuesday through Sunday, 4:30 AM – 7:00 AM. - **Delivery Zones:** - **Zone A (Urban Core):** daily drops, Tuesday–Sunday. - **Zone B (Outer Metro):** Tuesday, Thursday, and Saturday drops only. - **Route Timing:** Drivers give a 15-minute arrival text. Within a window, routes run in a fixed order set by the dispatcher."}]

[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-CAT-003",
    "category": "Catering & Events",
    "question": "What are your deposit and cancellation terms for events?",
    "answer": "A 50% non-refundable deposit is due at contract signing, and the balance is due 14 days before the event. If you cancel 30 or more days ahead we keep the deposit. If you cancel 14-29 days ahead we retain 50% of the contract value, and under 14 days we retain 100%.",
    "escalate_to_human": true
}"}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-CAT-001",
    "category": "Catering & Events",
    "question": "How far in advance do I need to book a wedding cake or dessert table?",
    "answer": "We require a minimum of 6 weeks notice for wedding orders and large event catering (100+ guests), 14 days for smaller custom celebratory cakes, and 7 days for small wholesale event trays. Peak wedding season dates (May-October) can close up to 6 months ahead, so early booking is recommended.",
    "escalate_to_human": false
}"}, {"source": "CATERING_AND_CUSTOM_CAKES.md", "quote": "- **Deposit:** 50% non-refundable deposit required at contract signing to reserve the event date. - **Final Balance:** Remaining balance must be paid in full 14 days prior to the event date. - **Cancellations:** - 30+ days prior: deposit retained. - 14–29 days prior: 50% of contract value retained. - Under 14 days: 100% of contract value retained. - **Guest Count Changes:** Final guest count is due 14 days before the event. It can increase by up to 10% within that window, subject to capacity. It cannot decrease after that date."}, {"source": "CATERING_AND_CUSTOM_CAKES.md", "quote": "- **Weddings & Large Events (100+ guests):** Minimum **6 weeks** notice required. Peak-season dates (May–October) close up to 6 months in advance. - **Bespoke Celebratory Cakes:** Minimum **14 days** notice required. - **Small Wholesale Event Trays:** Minimum **7 days** notice required. - **Rush Requests:** We cannot accommodate bookings inside these windows. Our sourdough cake layers and laminated doughs need 18–36 hours of fermentation, and decorating takes more time on top of that."}]

