[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-RET-001",
    "category": "Daily Retail & Orders",
    "question": "What time do you usually sell out of Country Sourdough?",
    "answer": "Our daily counter supply generally sells out between 11:30 AM and 1:00 PM on weekdays, and often before 11:00 AM on weekends. We strongly recommend placing a pre-order through our website 48 hours in advance to guarantee your items.",
    "escalate_to_human": false
}"}, {"source": "WHOLESALE_ORDERING_GUIDE.md", "quote": "Our sourdough breads undergo a mandatory 24-to-36-hour cold fermentation cycle. Because we use no commercial yeast or dough accelerants, **all wholesale orders require a strict 48-hour advance notice**. - **Standing Order Freeze:** Standing orders lock at **2:00 PM** two days prior to delivery. - **Order Modifications:** Additions or reductions must be submitted through the B2B Portal before the 2:00 PM cutoff. Late modifications cannot be accommodated, because the dough is already mixed and committed. - **No Same-Day or Next-Day Orders:** We do not offer rush orders at any price. | Order Placed By (2:00 PM) | Fermentation & Proofing Window | Delivery Window | | :--- | :--- | :--- | | **Sunday** | Monday | **Tuesday Morning** | | **Monday** | Tuesday | **Wednesday Morning** | | **Tuesday** | Wednesday | **Thursday Morning** | | **Wednesday** | Thursday | **Friday Morning** | | **Thursday** | Friday | **Saturday Morning** | | **Friday** | Saturday | **Sunday Morning** | *Table Summary:* [1. The 48-Hour Fermentation Lead Time Rule] - Order Placed By (2:00 PM): Sunday | Fermentation & Proofing Window: Monday | Delivery Window: Tuesday Morning - Order Placed By (2:00 PM): Monday | Fermentation & Proofing Window: Tuesday | Delivery Window: Wednesday Morning - Order Placed By (2:00 PM): Tuesday | Fermentation & Proofing Window: Wednesday | Delivery Window: Thursday Morning - Order Placed By (2:00 PM): Wednesday | Fermentation & Proofing Window: Thursday | Delivery Window: Friday Morning - Order Placed By (2:00 PM): Thursday | Fermentation & Proofing Window: Friday | Delivery Window: Saturday Morning - Order Placed By (2:00 PM): Friday | Fermentation & Proofing Window: Saturday | Delivery Window: Sunday Morning *Note: Retail counter and delivery routes are closed on Mondays. Orders placed on Saturday before 2:00 PM are treated as placed for Monday and are not deliverable. They roll to the Sunday cutoff and deliver Tuesday.*"}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-RET-006",
    "category": "Daily Retail & Orders",
    "question": "I received the wrong item or a damaged loaf in my retail order. What now?",
    "answer": "We're sorry about that. Please bring the item or a photo to the counter, or contact us within 24 hours of pickup, and our team will arrange a replacement or refund.",
    "escalate_to_human": true
}"}]

[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-WHO-005",
    "category": "Wholesale Accounts",
    "question": "Can you deliver to an outdoor lockbox in winter?",
    "answer": "Not from November 1 through April 1. Exterior lockbox drops are prohibited in winter to prevent thermal shock to the bread. We need access to a walk-in cooler or a food-safe staging counter indoors via a keycode or key.",
    "escalate_to_human": false
}"}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-RET-005",
    "category": "Daily Retail & Orders",
    "question": "Which breads are baked on which days?",
    "answer": "Country Sourdough and Sesame Baguettes are baked Tuesday through Sunday. Seeded Dark Rye is baked Tuesday, Thursday, Saturday, and Sunday. Spelt Boule is baked Wednesday, Friday, Saturday, and Sunday. Einkorn Honey Loaf is baked Thursday, Saturday, and Sunday. Seasonal specials are posted on our website each week.",
    "escalate_to_human": false
}"}, {"source": "WHOLESALE_ORDERING_GUIDE.md", "quote": "- **Access Requirements:** Partners must supply a reliable keycode or lockbox key for entry. - **Drop Location:** Drops are made directly to the partner's designated walk-in cooler or food-safe staging counter. Fresh bread is placed in breathable paper or cloth bags, never sealed plastic. - **Cold Weather Protection:** From Nov 1 to Apr 1, exterior lockbox drops are strictly prohibited to prevent thermal shock. A staffed or interior access point is required. - **Refrigeration Warning:** Do not refrigerate bread. Cold storage speeds staling (see `BREAD_STORAGE_AND_REVIVAL.md`)."}, {"source": "BREAD_STORAGE_AND_REVIVAL.md", "quote": "**Cinder & Salt Bakery** — *Wild Yeast. Heritage Grain. Honest Craft.* Our loaves contain only flour, water, and sea salt, with no preservatives. That is what makes them honest, and it also means they need a little care."}]

