esday.*"}]

[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-WHO-004",
    "category": "Wholesale Accounts",
    "question": "What are your payment terms?",
    "answer": "Terms are Net-15 via automated ACH through the wholesale portal. Invoices generate when the delivery departs. New accounts need credit approval before the first delivery, and balances more than 15 days past due pause deliveries.",
    "escalate_to_human": false
}"}, {"source": "WHOLESALE_ORDERING_GUIDE.md", "quote": "- **Credit Application:** New accounts submit a credit application and are approved before first delivery. Approval typically takes 3 business days. - **Payment Terms:** Net-15 via automated ACH through the wholesale portal. Invoices generate upon delivery departure. - **Late Payment:** Balances more than 15 days past due pause deliveries. A 1.5% monthly late fee applies after day 30. - **Quality Claims:** Missing, damaged, or unsatisfactory items must be reported within **12 hours of delivery drop** with cross-section photos. Approved claims are credited to the next invoice."}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-WHO-002",
    "category": "Wholesale Accounts",
    "question": "What is the minimum order for wholesale delivery?",
