[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-CAT-001",
    "category": "Catering & Events",
    "question": "How far in advance do I need to book a wedding cake or dessert table?",
    "answer": "We require a minimum of 6 weeks notice for wedding orders and large event catering (100+ guests), 14 days for smaller custom celebratory cakes, and 7 days for small wholesale event trays. Peak wedding season dates (May-October) can close up to 6 months ahead, so early booking is recommended.",
    "escalate_to_human": false
}"}, {"source": "CATERING_AND_CUSTOM_CAKES.md", "quote": "- **Delivery Fee:** $35.00 within Zone A (Urban Core) and $65.00 within Zone B (Outer Metro). Locations beyond our zones are quoted individually. - **Delivery Window:** We deliver and set up during a 2-hour window agreed in your contract, finishing at least 90 minutes before service. - **Venue Requirements:** A level table, shade, and a clear loading path. A refrigerated space within the venue is strongly recommended for tiered cakes. - **Tiered Cakes:** Cakes of three or more tiers are assembled on site by a staff member, and an on-site fee of $100.00 applies. - **Equipment:** Stands, boards, and linens are provided on loan with a refundable $75.00 deposit. They must be returned within 5 days. - **Closed Mondays:** Delivery and pickup are not available on Mondays."}, {"source": "CATERING_AND_CUSTOM_CAKES.md", "quote": "- **Weddings & Large Events (100+ guests):** Minimum **6 weeks** notice required. Peak-season dates (May–October) close up to 6 months in advance. - **Bespoke Celebratory Cakes:** Minimum **14 days** notice required. - **Small Wholesale Event Trays:** Minimum **7 days** notice required. - **Rush Requests:** We cannot accommodate bookings inside these windows. Our sourdough cake layers and laminated doughs need 18–36 hours of fermentation, and decorating takes more time on top of that."}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-CAT-002",
    "category": "Catering & Events",
    "question": "How does the tasting box work, and what does it cost?",
    "answer": "A tasting box is $45.00 and includes 4 sourdough cake options and 3 seasonal buttercreams or preserves. Boxes are prepared on the 1st and 3rd Saturday of each month and are available for pickup from 10:00 AM to 1:00 PM. The fee is credited toward any final catering contract over $300.00.",
    "escalate_to_human": false
}"}]

[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-WHO-004",
    "category": "Wholesale Accounts",
    "question": "What are your payment terms?",
    "answer": "Terms are Net-15 via automated ACH through the wholesale portal. Invoices generate when the delivery departs. New accounts need credit approval before the first delivery, and balances more than 15 days past due pause deliveries.",
    "escalate_to_human": false
}"}, {"source": "WHOLESALE_ORDERING_GUIDE.md", "quote": "- **Credit Application:** New accounts submit a credit application and are approved before first delivery. Approval typically takes 3 business days. - **Payment Terms:** Net-15 via automated ACH through the wholesale portal. Invoices generate upon delivery departure. - **Late Payment:** Balances more than 15 days past due pause deliveries. A 1.5% monthly late fee applies after day 30. - **Quality Claims:** Missing, damaged, or unsatisfactory items must be reported within **12 hours of delivery drop** with cross-section photos. Approved claims are credited to the next invoice."}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-WHO-001",
    "category": "Wholesale Accounts",
    "question": "Can I modify my wholesale delivery order for tomorrow morning?",
    "answer": "All wholesale orders must adhere to our 48-hour fermentation lead time. Standing order modifications for tomorrow morning locked today at 2:00 PM. Any changes requested past 2:00 PM cannot be processed as our doughs are already in their final fermentation cycle.",
    "escalate_to_human": true
}"}, {"source": "CATERING_AND_CUSTOM_CAKES.md", "quote": "- **Delivery Fee:** $35.00 within Zone A (Urban Core) and $65.00 within Zone B (Outer Metro). Locations beyond our zones are quoted individually. - **Delivery Window:** We deliver and set up during a 2-hour window agreed in your contract, finishing at least 90 minutes before service. - **Venue Requirements:** A level table, shade, and a clear loading path. A refrigerated space within the venue is strongly recommended for tiered cakes. - **Tiered Cakes:** Cakes of three or more tiers are assembled on site by a staff member, and an on-site fee of $100.00 applies. - **Equipment:** Stands, boards, and linens are provided on loan with a refundable $75.00 deposit. They must be returned within 5 days. - **Closed Mondays:** Delivery and pickup are not available on Mondays."}]

[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-CAT-003",
    "category": "Catering & Events",
    "question": "What are your deposit and cancellation terms for events?",
    "answer": "A 50% non-refundable deposit is due at contract signing, and the balance is due 14 days before the event. If you cancel 30 or more days ahead we keep the deposit. If you cancel 14-29 days ahead we retain 50% of the contract value, and under 14 days we retain 100%.",
    "escalate_to_human": true
}"}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-CAT-001",
    "category": "Catering & Events",
    "question": "How far in advance do I need to book a wedding cake or dessert table?",
    "answer": "We require a minimum of 6 weeks notice for wedding orders and large event catering (100+ guests), 14 days for smaller custom celebratory cakes, and 7 days for small wholesale event trays. Peak wedding season dates (May-October) can close up to 6 months ahead, so early booking is recommended.",
    "escalate_to_human": false
}"}, {"source": "CATERING_AND_CUSTOM_CAKES.md", "quote": "- **Deposit:** 50% non-refundable deposit required at contract signing to reserve the event date. - **Final Balance:** Remaining balance must be paid in full 14 days prior to the event date. - **Cancellations:** - 30+ days prior: deposit retained. - 14–29 days prior: 50% of contract value retained. - Under 14 days: 100% of contract value retained. - **Guest Count Changes:** Final guest count is due 14 days before the event. It can increase by up to 10% within that window, subject to capacity. It cannot decrease after that date."}, {"source": "CATERING_AND_CUSTOM_CAKES.md", "quote": "- **Weddings & Large Events (100+ guests):** Minimum **6 weeks** notice required. Peak-season dates (May–October) close up to 6 months in advance. - **Bespoke Celebratory Cakes:** Minimum **14 days** notice required. - **Small Wholesale Event Trays:** Minimum **7 days** notice required. - **Rush Requests:** We cannot accommodate bookings inside these windows. Our sourdough cake layers and laminated doughs need 18–36 hours of fermentation, and decorating takes more time on top of that."}]

