[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-ALG-002",
    "category": "Allergens & Ingredients",
    "question": "Which major allergens are present in your facility?",
    "answer": "Wheat/gluten, rye, tree nuts (walnuts and almonds), sesame, dairy (butter, milk, cheese), and eggs are all handled in our facility. Nuts, sesame, dairy, and eggs use color-coded dedicated tools, but ovens, mixers, and the mill are shared, so cross-contact is possible. We do not guarantee any item is free of these allergens.",
    "escalate_to_human": false
}"}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-ALG-004",
    "category": "Allergens & Ingredients",
    "question": "Do you have a nut-free or sesame-free bread?",
    "answer": "Several breads contain no nut or sesame ingredients, such as the Country Sourdough and Spelt Boule. We bake plain loaves first, at 2:00 AM, before seeded and nut items at 4:00 AM, and we sanitize at 12:00 PM and 8:00 PM. Shared ovens and airborne particles mean we cannot guarantee a nut-free or sesame-free product, so people with severe allergies should not rely on us.",
    "escalate_to_human": false
}"}, {"source": "CATERING_AND_CUSTOM_CAKES.md", "quote": "We cannot guarantee any event item is free of wheat, tree nuts, sesame, dairy, or eggs. Please share all guest allergies in your intake form. We will give you full ingredient lists and cross-contact notes so you can plan, and we will tell you plainly if an item is not appropriate for a guest. See `ALLERGEN_SAFETY_PROTOCOL.md`."}]

[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-CAT-001",
    "category": "Catering & Events",
    "question": "How far in advance do I need to book a wedding cake or dessert table?",
    "answer": "We require a minimum of 6 weeks notice for wedding orders and large event catering (100+ guests), 14 days for smaller custom celebratory cakes, and 7 days for small wholesale event trays. Peak wedding season dates (May-October) can close up to 6 months ahead, so early booking is recommended.",
    "escalate_to_human": false
}"}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-CAT-004",
    "category": "Catering & Events",
    "question": "Can my buttercream cake be displayed outdoors in summer?",
    "answer": "Swiss meringue buttercream softens at 72\u00b0F (22\u00b0C) and collapses above 80\u00b0F (27\u00b0C). Above 72\u00b0F (22\u00b0C), outdoor display is limited to 2 hours maximum, and the cake must stay in complete shade because direct sunlight can cause collapse within 15 minutes. For hot events, ask us about a naked or fondant-finished cake.",
    "escalate_to_human": false
}"}, {"source": "CATERING_AND_CUSTOM_CAKES.md", "quote": "- **Weddings & Large Events (100+ guests):** Minimum **6 weeks** notice required. Peak-season dates (May–October) close up to 6 months in advance. - **Bespoke Celebratory Cakes:** Minimum **14 days** notice required. - **Small Wholesale Event Trays:** Minimum **7 days** notice required. - **Rush Requests:** We cannot accommodate bookings inside these windows. Our sourdough cake layers and laminated doughs need 18–36 hours of fermentation, and decorating takes more time on top of that."}, {"source": "CATERING_AND_CUSTOM_CAKES.md", "quote": "- **Delivery Fee:** $35.00 within Zone A (Urban Core) and $65.00 within Zone B (Outer Metro). Locations beyond our zones are quoted individually. - **Delivery Window:** We deliver and set up during a 2-hour window agreed in your contract, finishing at least 90 minutes before service. - **Venue Requirements:** A level table, shade, and a clear loading path. A refrigerated space within the venue is strongly recommended for tiered cakes. - **Tiered Cakes:** Cakes of three or more tiers are assembled on site by a staff member, and an on-site fee of $100.00 applies. - **Equipment:** Stands, boards, and linens are provided on loan with a refundable $75.00 deposit. They must be returned within 5 days. - **Closed Mondays:** Delivery and pickup are not available on Mondays."}]

