[{"source": "WHOLESALE_ORDERING_GUIDE.md", "quote": "- **Access Requirements:** Partners must supply a reliable keycode or lockbox key for entry. - **Drop Location:** Drops are made directly to the partner's designated walk-in cooler or food-safe staging counter. Fresh bread is placed in breathable paper or cloth bags, never sealed plastic. - **Cold Weather Protection:** From Nov 1 to Apr 1, exterior lockbox drops are strictly prohibited to prevent thermal shock. A staffed or interior access point is required. - **Refrigeration Warning:** Do not refrigerate bread. Cold storage speeds staling (see `BREAD_STORAGE_AND_REVIVAL.md`)."}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-STR-001",
    "category": "Bread Care & Storage",
    "question": "Should I keep my sourdough loaf in the refrigerator?",
    "answer": "Never refrigerate fresh artisan bread. Refrigerator temperatures (35\u00b0F-42\u00b0F / 1\u00b0C-5\u00b0C) accelerate starch retrogradation by up to 300%, causing the bread to dry out and go stale much faster. Store it cut-side down on a wooden board for days 1-2, then in a linen or paper bag for days 3-5.",
    "escalate_to_human": false
}"}, {"source": "BREAD_STORAGE_AND_REVIVAL.md", "quote": "- **Days 1–2:** Place the loaf cut-side down directly on a wooden cutting board at room temperature. The cut face protects the crumb and the crust stays crisp. - **Days 3–5:** Transfer the loaf into an unbleached linen bread bag or brown paper sack. Avoid airtight plastic bags, which soften the crust and encourage mold. - **Location:** Keep away from the stove, direct sun, and humid spots. Ideal room temperature is 65°F–72°F (18°C–22°C)."}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-STR-002",
    "category": "Bread Care & Storage",
    "question": "How do I revive a stale loaf?",
    "answer": "Preheat your oven to 375\u00b0F (190\u00b0C). Run the unsliced loaf under cold water for 3 to 5 seconds, or spritz it well, then bake it directly on the center rack for 6 to 8 minutes. Rest for 5 minutes before slicing. It works best on loaves up to about 3 days old.",
    "escalate_to_human": false
}"}]

[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-ALG-004",
    "category": "Allergens & Ingredients",
    "question": "Do you have a nut-free or sesame-free bread?",
    "answer": "Several breads contain no nut or sesame ingredients, such as the Country Sourdough and Spelt Boule. We bake plain loaves first, at 2:00 AM, before seeded and nut items at 4:00 AM, and we sanitize at 12:00 PM and 8:00 PM. Shared ovens and airborne particles mean we cannot guarantee a nut-free or sesame-free product, so people with severe allergies should not rely on us.",
    "escalate_to_human": false
}"}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-ALG-002",
    "category": "Allergens & Ingredients",
    "question": "Which major allergens are present in your facility?",
    "answer": "Wheat/gluten, rye, tree nuts (walnuts and almonds), sesame, dairy (butter, milk, cheese), and eggs are all handled in our facility. Nuts, sesame, dairy, and eggs use color-coded dedicated tools, but ovens, mixers, and the mill are shared, so cross-contact is possible. We do not guarantee any item is free of these allergens.",
    "escalate_to_human": false
}"}, {"source": "ALLERGEN_SAFETY_PROTOCOL.md", "quote": "- Every retail item carries a label with ingredients and a "Contains" statement. - A posted notice at the counter and on the website reads: *"Our facility is not celiac-safe. All items may contain traces of wheat, tree nuts, sesame, dairy, and eggs."* - Customers with allergies are never told an item is "safe". They are told what is in it and what is nearby. - Any question we cannot answer from the allergen matrix is passed to the Head Baker, and no guess is offered."}]

[{"source": "CATERING_AND_CUSTOM_CAKES.md", "quote": "- **Delivery Fee:** $35.00 within Zone A (Urban Core) and $65.00 within Zone B (Outer Metro). Locations beyond our zones are quoted individually. - **Delivery Window:** We deliver and set up during a 2-hour window agreed in your contract, finishing at least 90 minutes before service. - **Venue Requirements:** A level table, shade, and a clear loading path. A refrigerated space within the venue is strongly recommended for tiered cakes. - **Tiered Cakes:** Cakes of three or more tiers are assembled on site by a staff member, and an on-site fee of $100.00 applies. - **Equipment:** Stands, boards, and linens are provided on loan with a refundable $75.00 deposit. They must be returned within 5 days. - **Closed Mondays:** Delivery and pickup are not available on Mondays."}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-CAT-002",
    "category": "Catering & Events",
    "question": "How does the tasting box work, and what does it cost?",
    "answer": "A tasting box is $45.00 and includes 4 sourdough cake options and 3 seasonal buttercreams or preserves. Boxes are prepared on the 1st and 3rd Saturday of each month and are available for pickup from 10:00 AM to 1:00 PM. The fee is credited toward any final catering contract over $300.00.",
    "escalate_to_human": false
}"}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-CAT-001",
    "category": "Catering & Events",
    "question": "How far in advance do I need to book a wedding cake or dessert table?",
    "answer": "We require a minimum of 6 weeks notice for wedding orders and large event catering (100+ guests), 14 days for smaller custom celebratory cakes, and 7 days for small wholesale event trays. Peak wedding season dates (May-October) can close up to 6 months ahead, so early booking is recommended.",
    "escalate_to_human": false
}"}, {"source": "CATERING_AND_CUSTOM_CAKES.md", "quote": "- **Fee:** $45.00 per tasting box (includes 4 sourdough cake options and 3 seasonal buttercreams/preserves). - **Credit:** The $45.00 fee is credited toward any final catering contract exceeding **$300.00**. - **Pickup Schedule:** Boxes are prepared on the 1st and 3rd Saturday of every month and are available for pickup between 10:00 AM and 1:00 PM. - **Reservation:** Tasting boxes must be reserved at least 7 days in advance. Unclaimed boxes are not held past 1:00 PM. - **Allergen Note:** Tasting boxes are produced in our standard facility. Tree nuts, dairy, eggs, wheat, and sesame may be present. Our facility is **not celiac-safe**."}]

