esday.*"}]

[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-ALG-002",
    "category": "Allergens & Ingredients",
    "question": "Which major allergens are present in your facility?",
    "answer": "Wheat/gluten, rye, tree nuts (walnuts and almonds), sesame, dairy (butter, milk, cheese), and eggs are all handled in our facility. Nuts, sesame, dairy, and eggs use color-coded dedicated tools, but ovens, mixers, and the mill are shared, so cross-contact is possible. We do not guarantee any item is free of these allergens.",
    "escalate_to_human": false
}"}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-ALG-001",
    "category": "Allergens & Ingredients",
    "question": "Are your sourdough breads safe for someone with Celiac Disease?",
    "answer": "No. While our 24-36 hour wild fermentation process breaks down some starches and makes bread easier to digest for many gluten-sensitive people, our facility actively stone-mills grains on-site. Airborne flour particles are present throughout the bakery. We are NOT a certified celiac-safe environment, and we do not make certified gluten-free products.",
    "escalate_to_human": false
}"}, {"source": "ALLERGEN_SAFETY_PROTOCOL.md", "quote": "- Every retail item carries a label with ingredients and a "Contains" statement. - A posted notice at the counter and on the website reads: *"Our facility is not celiac-safe. All items may contain traces of wheat, tree nuts, sesame, dairy, and eggs."* - Customers with allergies are never told an item is "safe". They are told what is in it and what is nearby. - Any question we cannot answer from the allergen matrix is passed to the Head Baker, and no guess is offered."}]

[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-SIZ-005",
    "category": "Sizing & Fit",
    "question": "Can I get my sleeves hemmed, and can I return a hemmed coat?",
    "answer": "Custom sleeve hemming is available in 0.5 inch increments, up to 3 inches shorter, and adds 5 to 7 business days. Altered items are final sale and excluded from the 45-day return window, so be sure of your measurements first.",
    "escalate_to_human": false
}"}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-REP-001",
    "category": "Warranty & Repair",
    "question": "What is covered under the Iron & Oak Heritage Guarantee?",
    "answer": "Our Heritage Guarantee covers structural failures, blown seams, detached rivets, zipper teeth failure, and broken brass hardware resulting from regular field use for the lifetime of the product. It excludes aesthetic patina, deliberate abuse, pet damage, and unauthorized third-party alterations.",
    "escalate_to_human": false
}"}, {"source": "WHOLESALE_SOP.md", "quote": "| Tier | Quantity (units per order) | Discount off MSRP | | :--- | :--- | :--- | | **Tier 1** | 25–99 units | 40% | | **Tier 2** | 100–499 units | 48% | | **Tier 3** | 500+ units | 55% | *Table Summary:* [1. Tiered Minimum Order Quantities (MOQ)] - Tier: Tier 1 | Quantity (units per order): 25–99 units | Discount off MSRP: 40% - Tier: Tier 2 | Quantity (units per order): 100–499 units | Discount off MSRP: 48% - Tier: Tier 3 | Quantity (units per order): 500+ units | Discount off MSRP: 55% - A "unit" is one finished item (one coat, one belt, one pair of pants). Mixed SKUs may be combined to reach a tier. - Orders of fewer than 25 units are not wholesale and are handled through retail or a gift program. - Tier pricing is locked for **12 months** from account approval, and Tier 2 and 3 accounts can set blanket orders with scheduled releases. - **Sample Program:** Up to 3 sample units are available at Tier 1 pricing, credited back if a first order of 25+ units is placed within 60 days."}, {"source": "sizing_specs.json", "quote": "custom_tailoring_disclaimer:
{
    "sleeve_hem_requests": "Custom sleeve hemming is available on request on outerwear, in 0.5 inch increments, up to 3 inches shorter.",
    "impact_on_returns": "Items with altered sleeve hems are final sale and excluded from the 45-day field trial return window.",
    "lead_time_days": "Add 5 to 7 business days to standard order processing."
}"}]

[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-REP-005",
    "category": "Warranty & Repair",
    "question": "My coat is damaged beyond repair. What are my options?",
    "answer": "When structural repair would compromise safety or integrity, you receive a 40% trade-in credit toward a replacement item, valid for 12 months. A bench craftsperson makes the repair-versus-replace call and we explain it with photos.",
    "escalate_to_human": true
}"}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-ORD-002",
    "category": "Orders & Shipping",
    "question": "What is your return policy?",
    "answer": "A 45-day field trial. Return unwashed items in original condition with tags attached for a full refund to your original payment method. There are no restocking fees, and inspections are done within 3 business days of receipt. Domestic return shipping is $7.95 deducted from the refund, except for exchanges and defects.",
    "escalate_to_human": false
}"}, {"source": "RETURNS_AND_EXCHANGES.md", "quote": "The following are non-returnable and excluded from refund policies: - Custom monogrammed leather goods. - Altered sleeve hems and any other custom tailoring. - Factory seconds. - Archived sale batches, labeled "Final Sale" at checkout. - Gift cards. Monogrammed or hemmed items are still covered by the Heritage Guarantee for defects."}, {"source": "RETURNS_AND_EXCHANGES.md", "quote": "Test your gear for up to **45 days** from the delivery date. Items returned in **unwashed, original condition with tags attached** receive full refunds to the original payment method. **Eligible:** - Unwashed and unaltered. Light try-on and trail testing is fine. - Original tags attached. - Returned within 45 days of delivery. **Not Eligible:** - Washed, soiled, stained, or damaged items. (If gear fails from defects, use `REPAIR_POLICY.md` instead.) - Items with pet hair, strong odor, or smoke."}]

[{"source": "REPAIR_POLICY.md", "quote": "If an item falls outside the guarantee, we will send you a quote **before** any work begins. You approve, or we return the item unrepaired. Typical repair price ranges: | Repair | Price Range | | :--- | :--- | | Seam re-stitch (up to 12 in.) | $15–$30 | | Zipper replacement | $45–$75 | | Rivet or snap replacement (each) | $5–$10 | | Belt buckle or keeper replacement | $20–$40 | | Leather re-conditioning and re-dye | $35–$60 | *Table Summary:* [4. Non-Warranty (Paid) Repairs] - Repair: Seam re-stitch (up to 12 in.) | Price Range: $15–$30 - Repair: Zipper replacement | Price Range: $45–$75 - Repair: Rivet or snap replacement (each) | Price Range: $5–$10 - Repair: Belt buckle or keeper replacement | Price Range: $20–$40 - Repair: Leather re-conditioning and re-dye | Price Range: $35–$60 Quote approval window is 10 days. Quotes are binding for 30 days."}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-REP-006",
    "category": "Warranty & Repair",
    "question": "Is a repair that isn't covered by the guarantee still possible?",
    "answer": "Yes. We quote the work before we start and you approve it or we send the item back unrepaired. Typical prices run $15 to $30 for a seam re-stitch and $45 to $75 for a zipper replacement. The quote is binding for 30 days.",
    "escalate_to_human": false
}"}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-REP-005",
    "category": "Warranty & Repair",
    "question": "My coat is damaged beyond repair. What are my options?",
    "answer": "When structural repair would compromise safety or integrity, you receive a 40% trade-in credit toward a replacement item, valid for 12 months. A bench craftsperson makes the repair-versus-replace call and we explain it with photos.",
    "escalate_to_human": true
}"}, {"source": "REPAIR_POLICY.md", "quote": "1. **Photo Triage:** Submit clear photos of the damage (close-up plus full item, in daylight) through the customer intake portal. 2. **RMA Issuance:** Receive a Return Merchandise Authorization (RMA) number within **24 hours** (business hours, Mon–Fri). Write the RMA number on the outside of the box. 3. **Incoming Shipping:** Ship the gear to our bench workshop. The customer covers incoming shipping. 4. **Bench Repair:** Our craftsmen repair the item using original heavy-gauge thread and solid brass hardware. Average repair cycle is **10–14 business days** from receipt. 5. **Return Shipping:** The restored item is returned with complimentary ground freight (typically 3 to 7 days, depending on where you are). **Before You Ship** - Empty the pockets and remove personal items. - Do not wash the garment. Dirty is fine. Washing can hide or worsen the damage. - Pack in a sturdy box or mailer. We recommend tracked shipping with insurance."}]

[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-WHO-004",
    "category": "Wholesale & B2B",
    "question": "Do you handle corporate gifting and tax-exempt purchases?",
    "answer": "Yes, for orders of 25 or more units. Tax-exempt buyers must provide a valid certificate before invoicing. Your account manager will help with gift packaging and delivery schedules.",
