[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-WHO-004",
    "category": "Wholesale & B2B",
    "question": "Do you handle corporate gifting and tax-exempt purchases?",
    "answer": "Yes, for orders of 25 or more units. Tax-exempt buyers must provide a valid certificate before invoicing. Your account manager will help with gift packaging and delivery schedules.",
    "escalate_to_human": true
}"}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-ORD-002",
    "category": "Orders & Shipping",
    "question": "What is your return policy?",
    "answer": "A 45-day field trial. Return unwashed items in original condition with tags attached for a full refund to your original payment method. There are no restocking fees, and inspections are done within 3 business days of receipt. Domestic return shipping is $7.95 deducted from the refund, except for exchanges and defects.",
    "escalate_to_human": false
}"}, {"source": "WHOLESALE_SOP.md", "quote": "- **Standard Terms:** **Net-30** upon approved credit evaluation. New accounts may begin with a credit limit of $5,000 and increase after 6 months of on-time payment. - **Customized Batches:** **50% deposit** is required on custom co-branded production batches, with the balance due Net-30 from shipment. - **Payment Methods:** ACH, wire, or check. Credit cards are accepted for orders under $2,500 with a 3% processing fee. - **Late Payments:** A 1.5% monthly fee applies after 30 days. Accounts more than 45 days past due are placed on hold."}, {"source": "RETURNS_AND_EXCHANGES.md", "quote": "The following are non-returnable and excluded from refund policies: - Custom monogrammed leather goods. - Altered sleeve hems and any other custom tailoring. - Factory seconds. - Archived sale batches, labeled "Final Sale" at checkout. - Gift cards. Monogrammed or hemmed items are still covered by the Heritage Guarantee for defects."}]

[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-ORD-005",
    "category": "Orders & Shipping",
    "question": "My package arrived damaged or with the wrong item.",
    "answer": "Contact us within 14 days of delivery with photos. We ship a replacement or refund in full with free return shipping.",
    "escalate_to_human": true
}"}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-ORD-004",
    "category": "Orders & Shipping",
    "question": "Which items can't be returned?",
    "answer": "Custom monogrammed leather goods, altered sleeve hems, factory seconds, archived sale batches marked Final Sale, and gift cards. These are still covered by the Heritage Guarantee for defects.",
    "escalate_to_human": false
}"}, {"source": "REPAIR_POLICY.md", "quote": "1. **Photo Triage:** Submit clear photos of the damage (close-up plus full item, in daylight) through the customer intake portal. 2. **RMA Issuance:** Receive a Return Merchandise Authorization (RMA) number within **24 hours** (business hours, Mon–Fri). Write the RMA number on the outside of the box. 3. **Incoming Shipping:** Ship the gear to our bench workshop. The customer covers incoming shipping. 4. **Bench Repair:** Our craftsmen repair the item using original heavy-gauge thread and solid brass hardware. Average repair cycle is **10–14 business days** from receipt. 5. **Return Shipping:** The restored item is returned with complimentary ground freight (typically 3 to 7 days, depending on where you are). **Before You Ship** - Empty the pockets and remove personal items. - Do not wash the garment. Dirty is fine. Washing can hide or worsen the damage. - Pack in a sturdy box or mailer. We recommend tracked shipping with insurance."}]

