[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-WHO-002",
    "category": "Wholesale & B2B",
    "question": "What are your wholesale tiers and discounts?",
    "answer": "Tier 1 is 25 to 99 units at 40% off MSRP. Tier 2 is 100 to 499 units at 48% off. Tier 3 is 500 or more units at 55% off. Mixed SKUs count toward the tier.",
    "escalate_to_human": false
}"}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-ORD-001",
    "category": "Orders & Shipping",
    "question": "How long does shipping take?",
    "answer": "Standard ground is 3 to 7 business days, free over $150.00 and $9.95 otherwise. Expedited 2-day is $24.95 and overnight is $39.95. Orders placed before 2:00 PM Mountain, Monday through Friday, ship the same or next business day.",
    "escalate_to_human": false
}"}, {"source": "WHOLESALE_SOP.md", "quote": "- **Manufacturing Lead Time:** Standard **4 to 6 weeks** production window from deposit receipt (or PO approval) to freight delivery. - **In-Stock Items:** Ship within 5 business days. - **Custom Co-Branded Orders:** 4 to 6 weeks after proof approval and deposit. - **Freight:** LTL freight for orders over 150 lb. Small-parcel ground for smaller shipments. Freight is prepaid and billed on the invoice, or the customer may use their own carrier. - **Freight Free Threshold:** Tier 3 orders ship freight-free within the contiguous U.S. - **Receiving:** Inspect and note damage on the bill of lading. Report shortages within **7 days** of delivery."}, {"source": "RETURNS_AND_EXCHANGES.md", "quote": "| Service | Delivery Time | Cost | | :--- | :--- | :--- | | Standard Ground | 3 to 7 business days | Free over $150.00; otherwise $9.95 | | Expedited 2-Day | 2 business days | $24.95 | | Overnight | 1 business day | $39.95 | *Table Summary:* [7. Orders & Shipping Reference] - Service: Standard Ground | Delivery Time: 3 to 7 business days | Cost: Free over $150.00; otherwise $9.95 - Service: Expedited 2-Day | Delivery Time: 2 business days | Cost: $24.95 - Service: Overnight | Delivery Time: 1 business day | Cost: $39.95 Orders placed before 2:00 PM Mountain, Monday–Friday, ship the same or next business day. Custom orders ship in 10 to 15 business days."}]

