[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-REP-002",
    "category": "Warranty & Repair",
    "question": "How do I submit a repair?",
    "answer": "Five steps. Submit clear photos through the customer intake portal, receive your RMA number within 24 hours, ship the gear to our bench workshop, wait 10 to 14 business days for repair, and we return it with complimentary ground shipping. Don't wash the item first.",
    "escalate_to_human": false
}"}, {"source": "REPAIR_POLICY.md", "quote": "1. **Photo Triage:** Submit clear photos of the damage (close-up plus full item, in daylight) through the customer intake portal. 2. **RMA Issuance:** Receive a Return Merchandise Authorization (RMA) number within **24 hours** (business hours, Mon–Fri). Write the RMA number on the outside of the box. 3. **Incoming Shipping:** Ship the gear to our bench workshop. The customer covers incoming shipping. 4. **Bench Repair:** Our craftsmen repair the item using original heavy-gauge thread and solid brass hardware. Average repair cycle is **10–14 business days** from receipt. 5. **Return Shipping:** The restored item is returned with complimentary ground freight (typically 3 to 7 days, depending on where you are). **Before You Ship** - Empty the pockets and remove personal items. - Do not wash the garment. Dirty is fine. Washing can hide or worsen the damage. - Pack in a sturdy box or mailer. We recommend tracked shipping with insurance."}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-REP-005",
    "category": "Warranty & Repair",
    "question": "My coat is damaged beyond repair. What are my options?",
    "answer": "When structural repair would compromise safety or integrity, you receive a 40% trade-in credit toward a replacement item, valid for 12 months. A bench craftsperson makes the repair-versus-replace call and we explain it with photos.",
    "escalate_to_human": true
}"}, {"source": "REPAIR_POLICY.md", "quote": "- **Patina is character, not a defect.** Scratches, darkening, creases, and fading are part of the gear's life. - **Neglect:** Gear left wet and balled up for weeks, mold growth, or leather cracked from never being conditioned is not covered. We will still quote you a paid repair. - **Abuse:** Cutting, burning, using a coat as a tow strap, or hitting a belt with an industrial tool is not "regular field use". - **Third-party work:** A tailor re-stitching a seam voids coverage for that seam only. The rest of the item stays covered."}]

[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-WHO-004",
    "category": "Wholesale & B2B",
    "question": "Do you handle corporate gifting and tax-exempt purchases?",
    "answer": "Yes, for orders of 25 or more units. Tax-exempt buyers must provide a valid certificate before invoicing. Your account manager will help with gift packaging and delivery schedules.",
    "escalate_to_human": true
}"}, {"source": "WHOLESALE_SOP.md", "quote": "1. Submit the commercial account application (business name, EIN, resale certificate or tax-exempt form if applicable, and trade references). 2. Credit check and review: **3 to 5 business days**. 3. Account manager assigned and portal access granted. Tax-exempt buyers must provide a valid certificate before invoicing. Orders shipped without a certificate are taxed where applicable."}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-SIZ-005",
    "category": "Sizing & Fit",
    "question": "Can I get my sleeves hemmed, and can I return a hemmed coat?",
    "answer": "Custom sleeve hemming is available in 0.5 inch increments, up to 3 inches shorter, and adds 5 to 7 business days. Altered items are final sale and excluded from the 45-day return window, so be sure of your measurements first.",
    "escalate_to_human": false
}"}, {"source": "RETURNS_AND_EXCHANGES.md", "quote": "The following are non-returnable and excluded from refund policies: - Custom monogrammed leather goods. - Altered sleeve hems and any other custom tailoring. - Factory seconds. - Archived sale batches, labeled "Final Sale" at checkout. - Gift cards. Monogrammed or hemmed items are still covered by the Heritage Guarantee for defects."}]

