[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-ORD-002",
    "category": "Orders & Shipping",
    "question": "What is your return policy?",
    "answer": "A 45-day field trial. Return unwashed items in original condition with tags attached for a full refund to your original payment method. There are no restocking fees, and inspections are done within 3 business days of receipt. Domestic return shipping is $7.95 deducted from the refund, except for exchanges and defects.",
    "escalate_to_human": false
}"}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-ORD-004",
    "category": "Orders & Shipping",
    "question": "Which items can't be returned?",
    "answer": "Custom monogrammed leather goods, altered sleeve hems, factory seconds, archived sale batches marked Final Sale, and gift cards. These are still covered by the Heritage Guarantee for defects.",
    "escalate_to_human": false
}"}, {"source": "RETURNS_AND_EXCHANGES.md", "quote": "1. Open the customer portal and select **Start a Return** with your order number. 2. Choose Return or Exchange and a reason. 3. Print the prepaid label (domestic) or show the QR code at a carrier drop-off. 4. Pack the item with tags and ship within 7 days of generating the label. 5. Track your return through the portal. - **Domestic Returns:** Return shipping is deducted from refunds ($7.95 flat), except for exchanges and defective items, which are free. - **International Returns:** Customer pays return shipping, and duties and taxes are not refundable."}, {"source": "RETURNS_AND_EXCHANGES.md", "quote": "The following are non-returnable and excluded from refund policies: - Custom monogrammed leather goods. - Altered sleeve hems and any other custom tailoring. - Factory seconds. - Archived sale batches, labeled "Final Sale" at checkout. - Gift cards. Monogrammed or hemmed items are still covered by the Heritage Guarantee for defects."}]

