[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-ORD-005",
    "category": "Orders & Shipping",
    "question": "My package arrived damaged or with the wrong item.",
    "answer": "Contact us within 14 days of delivery with photos. We ship a replacement or refund in full with free return shipping.",
    "escalate_to_human": true
}"}, {"source": "RETURNS_AND_EXCHANGES.md", "quote": "If you receive the wrong item or one damaged in transit, contact us within **14 days** of delivery with photos. We ship a replacement or refund in full, with free return shipping."}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-ORD-004",
    "category": "Orders & Shipping",
    "question": "Which items can't be returned?",
    "answer": "Custom monogrammed leather goods, altered sleeve hems, factory seconds, archived sale batches marked Final Sale, and gift cards. These are still covered by the Heritage Guarantee for defects.",
    "escalate_to_human": false
}"}, {"source": "REPAIR_POLICY.md", "quote": "1. **Photo Triage:** Submit clear photos of the damage (close-up plus full item, in daylight) through the customer intake portal. 2. **RMA Issuance:** Receive a Return Merchandise Authorization (RMA) number within **24 hours** (business hours, Mon–Fri). Write the RMA number on the outside of the box. 3. **Incoming Shipping:** Ship the gear to our bench workshop. The customer covers incoming shipping. 4. **Bench Repair:** Our craftsmen repair the item using original heavy-gauge thread and solid brass hardware. Average repair cycle is **10–14 business days** from receipt. 5. **Return Shipping:** The restored item is returned with complimentary ground freight (typically 3 to 7 days, depending on where you are). **Before You Ship** - Empty the pockets and remove personal items. - Do not wash the garment. Dirty is fine. Washing can hide or worsen the damage. - Pack in a sturdy box or mailer. We recommend tracked shipping with insurance."}]

[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-MAT-005",
    "category": "Product & Materials",
    "question": "How do I rewax my coat?",
    "answer": "Clean the canvas with cold water and a soft brush, then let it dry. Rub a paraffin/beeswax bar over the weave in circular motions, then melt it in with a hairdryer on medium or a heat gun on low, held 4 to 6 inches away. Cure it in a cool, dry place for 24 hours.",
    "escalate_to_human": false
}"}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-MAT-004",
    "category": "Product & Materials",
    "question": "Can I machine wash my waxed canvas coat?",
    "answer": "No. Machine washing or heat drying strips the wax and ruins the water resistance. Brush off dry mud, spot clean with cold water and a soft brush, and air dry. If you already washed it, you can rewax it.",
    "escalate_to_human": false
}"}, {"source": "CARE_GUIDE.md", "quote": "- Store gear in **breathable canvas storage bags** in well-ventilated spaces. Avoid plastic bags and sealed containers. - Keep the temperature between 50°F and 75°F (10°C and 24°C) and relative humidity under 60% where possible. - Avoid direct UV sunlight, which fades and dries both canvas and leather, and avoid damp basements, which promote mold growth and leather degradation. - Store coats on a wide hanger. Fold waxed canvas as little as possible, because hard creases can crack the wax. - Before storage, make sure everything is completely dry."}, {"source": "CARE_GUIDE.md", "quote": "Rewax once a year, or seasonally for heavy use, or whenever water stops beading. 1. **Clean:** Remove debris using cold water and a soft brush. Let the canvas dry completely. 2. **Apply:** Rub a paraffin/beeswax bar evenly across the canvas weave using circular motions. Focus on seams, shoulders, elbows, and pocket flaps. Use about **one 3 oz bar per coat**. 3. **Melt:** Use a heat gun on its low setting or a hairdryer on medium heat, held **4 to 6 inches (10 to 15 cm)** from the fabric, to melt the wax into the fibers. Keep it moving. Do not exceed about **150°F (65°C)** at the fabric surface. 4. **Even Out:** Wipe off any pooling wax with a clean cloth while it's warm. 5. **Cure:** Allow the canvas to cure flat or hanging in a cool, dry area for **24 hours**. Test on a hidden area first. Fresh wax may darken the canvas slightly."}]

