[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-REP-005",
    "category": "Warranty & Repair",
    "question": "My coat is damaged beyond repair. What are my options?",
    "answer": "When structural repair would compromise safety or integrity, you receive a 40% trade-in credit toward a replacement item, valid for 12 months. A bench craftsperson makes the repair-versus-replace call and we explain it with photos.",
    "escalate_to_human": true
}"}, {"source": "REPAIR_POLICY.md", "quote": "When structural repair would compromise safety or integrity, or the item is damaged beyond functional repair, the customer receives a **40% trade-in credit** toward a replacement item. - Credit is based on the **current retail price** of the replacement item and applies to a single purchase. - Credit is valid for **12 months**. - We recycle usable brass hardware and leather offcuts. - Trade-in credit is available for items outside the guarantee as well, at the discretion of the bench lead. - The decision on repair versus replacement is made by a bench craftsperson, and we will explain it with photos."}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-ORD-004",
    "category": "Orders & Shipping",
    "question": "Which items can't be returned?",
    "answer": "Custom monogrammed leather goods, altered sleeve hems, factory seconds, archived sale batches marked Final Sale, and gift cards. These are still covered by the Heritage Guarantee for defects.",
    "escalate_to_human": false
}"}, {"source": "REPAIR_POLICY.md", "quote": "- **Patina is character, not a defect.** Scratches, darkening, creases, and fading are part of the gear's life. - **Neglect:** Gear left wet and balled up for weeks, mold growth, or leather cracked from never being conditioned is not covered. We will still quote you a paid repair. - **Abuse:** Cutting, burning, using a coat as a tow strap, or hitting a belt with an industrial tool is not "regular field use". - **Third-party work:** A tailor re-stitching a seam voids coverage for that seam only. The rest of the item stays covered."}]

[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-WHO-004",
