[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-ORD-003",
    "category": "Orders & Shipping",
    "question": "How do I exchange for a different size?",
    "answer": "Start the exchange in the customer portal. A prepaid digital label is generated automatically for domestic size and color exchanges. Your first exchange per item is free.",
    "escalate_to_human": false
}"}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-SIZ-005",
    "category": "Sizing & Fit",
    "question": "Can I get my sleeves hemmed, and can I return a hemmed coat?",
    "answer": "Custom sleeve hemming is available in 0.5 inch increments, up to 3 inches shorter, and adds 5 to 7 business days. Altered items are final sale and excluded from the 45-day return window, so be sure of your measurements first.",
    "escalate_to_human": false
}"}, {"source": "RETURNS_AND_EXCHANGES.md", "quote": "Complimentary prepaid digital shipping labels are generated automatically via our customer portal for all domestic size and color exchanges. - We ship the replacement when the carrier shows your original item in transit **if** your account is in good standing, or when we receive it. - If the replacement costs more, we charge the difference. If it costs less, we refund the difference. - One free exchange per item. Further exchanges carry a $7.95 shipping charge. - Exchanges are subject to stock availability. If your size is out, we refund in full."}, {"source": "RETURNS_AND_EXCHANGES.md", "quote": "The following are non-returnable and excluded from refund policies: - Custom monogrammed leather goods. - Altered sleeve hems and any other custom tailoring. - Factory seconds. - Archived sale batches, labeled "Final Sale" at checkout. - Gift cards. Monogrammed or hemmed items are still covered by the Heritage Guarantee for defects."}]

[{"source": "faq_support_knowledgebase.json", "quote": "{
