[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-WHO-004",
    "category": "Wholesale & B2B",
    "question": "Do you handle corporate gifting and tax-exempt purchases?",
    "answer": "Yes, for orders of 25 or more units. Tax-exempt buyers must provide a valid certificate before invoicing. Your account manager will help with gift packaging and delivery schedules.",
    "escalate_to_human": true
}"}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-ORD-001",
    "category": "Orders & Shipping",
    "question": "How long does shipping take?",
    "answer": "Standard ground is 3 to 7 business days, free over $150.00 and $9.95 otherwise. Expedited 2-day is $24.95 and overnight is $39.95. Orders placed before 2:00 PM Mountain, Monday through Friday, ship the same or next business day.",
    "escalate_to_human": false
}"}, {"source": "RETURNS_AND_EXCHANGES.md", "quote": "| Service | Delivery Time | Cost | | :--- | :--- | :--- | | Standard Ground | 3 to 7 business days | Free over $150.00; otherwise $9.95 | | Expedited 2-Day | 2 business days | $24.95 | | Overnight | 1 business day | $39.95 | *Table Summary:* [7. Orders & Shipping Reference] - Service: Standard Ground | Delivery Time: 3 to 7 business days | Cost: Free over $150.00; otherwise $9.95 - Service: Expedited 2-Day | Delivery Time: 2 business days | Cost: $24.95 - Service: Overnight | Delivery Time: 1 business day | Cost: $39.95 Orders placed before 2:00 PM Mountain, Monday–Friday, ship the same or next business day. Custom orders ship in 10 to 15 business days."}, {"source": "WHOLESALE_SOP.md", "quote": "- **Manufacturing Lead Time:** Standard **4 to 6 weeks** production window from deposit receipt (or PO approval) to freight delivery. - **In-Stock Items:** Ship within 5 business days. - **Custom Co-Branded Orders:** 4 to 6 weeks after proof approval and deposit. - **Freight:** LTL freight for orders over 150 lb. Small-parcel ground for smaller shipments. Freight is prepaid and billed on the invoice, or the customer may use their own carrier. - **Freight Free Threshold:** Tier 3 orders ship freight-free within the contiguous U.S. - **Receiving:** Inspect and note damage on the bill of lading. Report shortages within **7 days** of delivery."}]

[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-REP-005",
    "category": "Warranty & Repair",
    "question": "My coat is damaged beyond repair. What are my options?",
    "answer": "When structural repair would compromise safety or integrity, you receive a 40% trade-in credit toward a replacement item, valid for 12 months. A bench craftsperson makes the repair-versus-replace call and we explain it with photos.",
    "escalate_to_human": true
}"}, {"source": "REPAIR_POLICY.md", "quote": "When structural repair would compromise safety or integrity, or the item is damaged beyond functional repair, the customer receives a **40% trade-in credit** toward a replacement item. - Credit is based on the **current retail price** of the replacement item and applies to a single purchase. - Credit is valid for **12 months**. - We recycle usable brass hardware and leather offcuts. - Trade-in credit is available for items outside the guarantee as well, at the discretion of the bench lead. - The decision on repair versus replacement is made by a bench craftsperson, and we will explain it with photos."}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-ORD-004",
    "category": "Orders & Shipping",
    "question": "Which items can't be returned?",
    "answer": "Custom monogrammed leather goods, altered sleeve hems, factory seconds, archived sale batches marked Final Sale, and gift cards. These are still covered by the Heritage Guarantee for defects.",
    "escalate_to_human": false
}"}, {"source": "RETURNS_AND_EXCHANGES.md", "quote": "Test your gear for up to **45 days** from the delivery date. Items returned in **unwashed, original condition with tags attached** receive full refunds to the original payment method. **Eligible:** - Unwashed and unaltered. Light try-on and trail testing is fine. - Original tags attached. - Returned within 45 days of delivery. **Not Eligible:** - Washed, soiled, stained, or damaged items. (If gear fails from defects, use `REPAIR_POLICY.md` instead.) - Items with pet hair, strong odor, or smoke."}]

[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-MAT-006",
    "category": "Product & Materials",
    "question": "My leather got soaked. What do I do?",
    "answer": "Blot it with a towel and dry it slowly at room temperature for 24 to 48 hours, away from heat and direct sun. Never use a radiator, stove, or hair dryer. Once dry, condition it. Heat-damaged leather cracks and is not covered by the guarantee.",
    "escalate_to_human": false
}"}, {"source": "CARE_GUIDE.md", "quote": "- **Biannual Conditioning:** Apply natural beeswax or neatsfoot oil balm every **6 months** to prevent dry cracking. - Dry climates (under 30% relative humidity): condition every **3 to 4 months**. - Humid climates (over 70%): condition every 6 months, and watch for mildew. - **How to Condition:** 1. Brush off dirt and dust. 2. Wipe with a damp cloth and let it dry for 1 hour at room temperature. 3. Work a **dime-sized amount** of balm in with a clean cloth, using small circles. 4. Let it absorb for 12 hours, then buff off the excess. - Don't over-oil. Too much oil softens the leather and makes it stretch. - **Cleaning Protocol:** Wipe with a damp cloth. Use saddle soap sparingly for deep mud or grease removal, and condition afterward. - **Prohibitions:** *Strictly no machine washing or heat drying.* High temperature strips natural oils and distorts the grain. Keep leather away from radiators, wood stoves, and car dashboards. - **If It Gets Soaked:** Blot with a towel, stuff boots or belts with paper if needed, and dry slowly at room temperature, for **24 to 48 hours**, out of direct sun. Condition after it is dry. - **Patina:** Darkening, scratches, and creases are normal. Veg-tan leather ages to a deeper color the more you use it. - **Hardware:** Solid brass tarnishes. A little tarnish is fine. To clean it, use a dry cloth. Avoid chemical polishes on leather."}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-MAT-003",
    "category": "Product & Materials",
    "question": "How often should I condition my leather?",
    "answer": "Every 6 months with natural beeswax or neatsfoot oil balm. In dry climates, every 3 to 4 months. Use a dime-sized amount, work it in with a clean cloth, wait 12 hours, and buff off the excess. Don't over-oil.",
    "escalate_to_human": false
}"}]

[{"source": "faq_support_knowledgebase.json", "quote": "{
