[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-ORD-005",
    "category": "Orders & Shipping",
    "question": "My package arrived damaged or with the wrong item.",
    "answer": "Contact us within 14 days of delivery with photos. We ship a replacement or refund in full with free return shipping.",
    "escalate_to_human": true
}"}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-ORD-004",
    "category": "Orders & Shipping",
    "question": "Which items can't be returned?",
    "answer": "Custom monogrammed leather goods, altered sleeve hems, factory seconds, archived sale batches marked Final Sale, and gift cards. These are still covered by the Heritage Guarantee for defects.",
    "escalate_to_human": false
}"}, {"source": "REPAIR_POLICY.md", "quote": "1. **Photo Triage:** Submit clear photos of the damage (close-up plus full item, in daylight) through the customer intake portal. 2. **RMA Issuance:** Receive a Return Merchandise Authorization (RMA) number within **24 hours** (business hours, Mon–Fri). Write the RMA number on the outside of the box. 3. **Incoming Shipping:** Ship the gear to our bench workshop. The customer covers incoming shipping. 4. **Bench Repair:** Our craftsmen repair the item using original heavy-gauge thread and solid brass hardware. Average repair cycle is **10–14 business days** from receipt. 5. **Return Shipping:** The restored item is returned with complimentary ground freight (typically 3 to 7 days, depending on where you are). **Before You Ship** - Empty the pockets and remove personal items. - Do not wash the garment. Dirty is fine. Washing can hide or worsen the damage. - Pack in a sturdy box or mailer. We recommend tracked shipping with insurance."}, {"source": "RETURNS_AND_EXCHANGES.md", "quote": "If you receive the wrong item or one damaged in transit, contact us within **14 days** of delivery with photos. We ship a replacement or refund in full, with free return shipping."}]

[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-REP-005",
    "category": "Warranty & Repair",
    "question": "My coat is damaged beyond repair. What are my options?",
    "answer": "When structural repair would compromise safety or integrity, you receive a 40% trade-in credit toward a replacement item, valid for 12 months. A bench craftsperson makes the repair-versus-replace call and we explain it with photos.",
    "escalate_to_human": true
}"}, {"source": "REPAIR_POLICY.md", "quote": "When structural repair would compromise safety or integrity, or the item is damaged beyond functional repair, the customer receives a **40% trade-in credit** toward a replacement item. - Credit is based on the **current retail price** of the replacement item and applies to a single purchase. - Credit is valid for **12 months**. - We recycle usable brass hardware and leather offcuts. - Trade-in credit is available for items outside the guarantee as well, at the discretion of the bench lead. - The decision on repair versus replacement is made by a bench craftsperson, and we will explain it with photos."}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-REP-002",
    "category": "Warranty & Repair",
    "question": "How do I submit a repair?",
    "answer": "Five steps. Submit clear photos through the customer intake portal, receive your RMA number within 24 hours, ship the gear to our bench workshop, wait 10 to 14 business days for repair, and we return it with complimentary ground shipping. Don't wash the item first.",
    "escalate_to_human": false
}"}, {"source": "REPAIR_POLICY.md", "quote": "1. **Photo Triage:** Submit clear photos of the damage (close-up plus full item, in daylight) through the customer intake portal. 2. **RMA Issuance:** Receive a Return Merchandise Authorization (RMA) number within **24 hours** (business hours, Mon–Fri). Write the RMA number on the outside of the box. 3. **Incoming Shipping:** Ship the gear to our bench workshop. The customer covers incoming shipping. 4. **Bench Repair:** Our craftsmen repair the item using original heavy-gauge thread and solid brass hardware. Average repair cycle is **10–14 business days** from receipt. 5. **Return Shipping:** The restored item is returned with complimentary ground freight (typically 3 to 7 days, depending on where you are). **Before You Ship** - Empty the pockets and remove personal items. - Do not wash the garment. Dirty is fine. Washing can hide or worsen the damage. - Pack in a sturdy box or mailer. We recommend tracked shipping with insurance."}]

[{"source": "RETURNS_AND_EXCHANGES.md", "quote": "Complimentary prepaid digital shipping labels are generated automatically via our customer portal for all domestic size and color exchanges. - We ship the replacement when the carrier shows your original item in transit **if** your account is in good standing, or when we receive it. - If the replacement costs more, we charge the difference. If it costs less, we refund the difference. - One free exchange per item. Further exchanges carry a $7.95 shipping charge. - Exchanges are subject to stock availability. If your size is out, we refund in full."}, {"source": "faq_support_knowledgebase.json", "quote": "{
