[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-WHO-004",
    "category": "Wholesale & B2B",
    "question": "Do you handle corporate gifting and tax-exempt purchases?",
    "answer": "Yes, for orders of 25 or more units. Tax-exempt buyers must provide a valid certificate before invoicing. Your account manager will help with gift packaging and delivery schedules.",
    "escalate_to_human": true
}"}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-WHO-001",
    "category": "Wholesale & B2B",
    "question": "Can we deboss our company logo onto wholesale leather field notebooks?",
    "answer": "Yes. We offer custom hot-stamp debossing on orders meeting our Tier 1 MOQ of 25 units. A one-time $150 brass die tooling fee applies, and artwork must be supplied as a vectorized PDF or AI file.",
    "escalate_to_human": false
}"}, {"source": "WHOLESALE_SOP.md", "quote": "Hot-stamp custom logo debossing is available across all leather goods. Co-branded apparel patches are available for Tier 2 and 3 accounts. - **Artwork:** Vector files (.AI or .PDF) are required. Raster files (JPG/PNG) are not accepted. - **Tool-and-Die Fee:** A one-time **$150 tool-and-die brass mold fee** applies per custom artwork submission. Reorders using the same die are free. - **Size Limits:** Maximum deboss area is **2.5 in. × 1.25 in.** on belts and **3 in. × 3 in.** on notebooks and wallets. Minimum line weight is 0.5 pt (1 mm gap between elements). - **Stamp Temperature:** Stamps are applied at roughly **230°F–260°F (110°C–127°C)**. - **Proof Approval:** A digital proof is sent within 3 business days of artwork receipt, and a physical sample deboss is available for $35.00. Production starts only after written proof approval. - **Brand Compliance:** We reserve the right to decline artwork that infringes a trademark or conflicts with our brand. - Custom branded goods are **final sale**."}, {"source": "RETURNS_AND_EXCHANGES.md", "quote": "The following are non-returnable and excluded from refund policies: - Custom monogrammed leather goods. - Altered sleeve hems and any other custom tailoring. - Factory seconds. - Archived sale batches, labeled "Final Sale" at checkout. - Gift cards. Monogrammed or hemmed items are still covered by the Heritage Guarantee for defects."}]

