[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-CAN-002",
    "category": "Booking & Cancellations",
    "question": "What is a lockout and what does it cost?",
    "answer": "A lockout means we can't enter within 20 minutes of the start of the arrival window, for example because of a wrong code or a missing key. It is billed at 100% of the scheduled service fee.",
    "escalate_to_human": true
}"}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-CAN-001",
    "category": "Booking & Cancellations",
    "question": "What happens if I need to cancel my cleaning appointment tomorrow?",
    "answer": "Appointments canceled with less than 24 hours notice are subject to a 100% service fee charge because our collective members are paid for their booked time. If canceled between 24 and 48 hours in advance, a $50 administrative fee applies. Cancellations with over 48 hours notice are completely free.",
    "escalate_to_human": true
}"}, {"source": "WALKTHROUGH_AND_INTAKE_SOP.md", "quote": "All recurring service contracts must undergo a foundational **Initial Deep Clean**. This baseline visit removes pre-existing buildup, limescale, and synthetic wax residues from previous chemical cleaners before beginning botanical maintenance. - **Duration:** Typically **2.0x to 2.5x** the standard maintenance time for the same square footage (for example, a 2,000 sq ft home that takes 150 minutes for maintenance will take about 5 to 6.25 hours of technician time for the deep clean). - **Added Tasks:** Interior oven and refrigerator, baseboards, door casings, window sills and tracks, cabinet interiors on request, descaling of fixtures, and detailed grout work. - **Why It Is Mandatory:** Botanical chemistry cannot lift old synthetic residues on its own, and the baseline sets a measurable standard for every visit after it. - **Short-Term Rental Properties:** A baseline deep clean is required before the first turnover. - **Pricing:** Quoted as a fixed price at the walkthrough. Rates are not charged beyond the quote unless conditions differ from the photos, and the client approves any change first."}, {"source": "service_scope_matrix.json", "quote": "{
    "name": "Interior cabinets (per kitchen)",
    "estimated_minutes_each": 45
}"}]

[{"source": "service_scope_matrix.json", "quote": "{
    "tier_id": "TIER-PCN-04",
    "tier_name": "Post-Construction Remediation",
    "frequency_options": [
        "One-time (three phases)",
        "Touch-up visit within 7 days"
    ],
    "requires_initial_deep_clean": false,
    "zones": {
        "phase_1_rough_debris_pass": [
            "Remove construction packaging, protective films, stickers, and tape residue",
            "Scrape paint splatter with plastic blades",
            "Rough sweep floors with HEPA capture"
        ],
        "phase_2_high_to_low_hepa_vacuuming": [
            "HEPA vacuum ceiling joists, fans, HVAC diffusers, and light fixtures",
            "HEPA vacuum door casings, window tracks, and cabinet tops",
            "HEPA vacuum baseboards and floors (99.97% at 0.3 microns)"
        ],
        "phase_3_wet_microfiber_sparkle_pass": [
