[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-CAN-001",
    "category": "Booking & Cancellations",
    "question": "What happens if I need to cancel my cleaning appointment tomorrow?",
    "answer": "Appointments canceled with less than 24 hours notice are subject to a 100% service fee charge because our collective members are paid for their booked time. If canceled between 24 and 48 hours in advance, a $50 administrative fee applies. Cancellations with over 48 hours notice are completely free.",
    "escalate_to_human": true
}"}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-SCP-005",
    "category": "Scope of Services",
    "question": "Do you provide commercial office cleaning?",
    "answer": "Yes. Nightly, 3x weekly, or weekly service covering workstations, restrooms, break rooms, and common areas, at about 45 minutes per 1,000 sq ft per technician. Our technicians are W-2 employees of the cooperative, so you see the same familiar faces.",
    "escalate_to_human": false
}"}, {"source": "WALKTHROUGH_AND_INTAKE_SOP.md", "quote": "| Item | Recorded | | :--- | :--- | | Square footage by room | Yes | | Floor types by room | Yes | | Sensitive surfaces | Yes | | Pre-existing damage (photo log) | Yes | | Pets, infants, allergies | Yes | | Access method and alarm details | Yes (encrypted) | | Parking and loading | Yes | | Water and power access | Yes | | Client-supplied cleaning products | Note: not used unless approved | *Table Summary:* [3. Walkthrough Checklist] - Item: Square footage by room | Recorded: Yes - Item: Floor types by room | Recorded: Yes - Item: Sensitive surfaces | Recorded: Yes - Item: Pre-existing damage (photo log) | Recorded: Yes - Item: Pets, infants, allergies | Recorded: Yes - Item: Access method and alarm details | Recorded: Yes (encrypted) - Item: Parking and loading | Recorded: Yes - Item: Water and power access | Recorded: Yes - Item: Client-supplied cleaning products | Recorded: Note: not used unless approved"}]

[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-CAN-004",
    "category": "Booking & Cancellations",
    "question": "How do you price a cleaning?",
    "answer": "Estimates use our scope matrix and a base rate of $55.00 per technician-hour. Maintenance cleans take about 75 minutes per 1,000 sq ft, short-term rental turnovers about 110 minutes, and commercial offices about 45 minutes. You receive a fixed-price proposal after your 30-minute walkthrough.",
    "escalate_to_human": false
}"}, {"source": "WALKTHROUGH_AND_INTAKE_SOP.md", "quote": "All recurring service contracts must undergo a foundational **Initial Deep Clean**. This baseline visit removes pre-existing buildup, limescale, and synthetic wax residues from previous chemical cleaners before beginning botanical maintenance. - **Duration:** Typically **2.0x to 2.5x** the standard maintenance time for the same square footage (for example, a 2,000 sq ft home that takes 150 minutes for maintenance will take about 5 to 6.25 hours of technician time for the deep clean). - **Added Tasks:** Interior oven and refrigerator, baseboards, door casings, window sills and tracks, cabinet interiors on request, descaling of fixtures, and detailed grout work. - **Why It Is Mandatory:** Botanical chemistry cannot lift old synthetic residues on its own, and the baseline sets a measurable standard for every visit after it. - **Short-Term Rental Properties:** A baseline deep clean is required before the first turnover. - **Pricing:** Quoted as a fixed price at the walkthrough. Rates are not charged beyond the quote unless conditions differ from the photos, and the client approves any change first."}, {"source": "service_scope_matrix.json", "quote": "scope_matrix_metadata:
{
    "company": "Kettle & Loom Cleaning Collective",
    "standard_version": "3.1",
    "currency": "USD",
    "base_hourly_rate_per_tech": 55.0,
    "labor_estimate_basis": "Technician minutes per 1,000 sq ft of conditioned space for one technician. Divide by team size for on-site duration.",
    "initial_deep_clean_multiplier": {
        "min": 2.0,
        "max": 2.5
    },
    "temperature_notes": {
        "dilution_water_f": "60-80",
        "dilution_water_c": "16-27",
        "chemical_storage_f": "50-80",
        "chemical_storage_c": "10-27"
    }
}"}]

[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-ECO-002",
    "category": "Chemical Safety & Eco-Standards",
    "question": "What ingredients do you use?",
    "answer": "Bio-Shield Disinfectant uses 0.05% thymol, OxyPure uses stabilized 3% hydrogen peroxide, Citrus-Loom Descaler uses 8% food-grade citric acid, and PureLoom Floor Wash is a saponified coconut and olive oil soap. We provide Safety Data Sheets for every product on request.",
    "escalate_to_human": false
}"}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-ECO-001",
    "category": "Chemical Safety & Eco-Standards",
    "question": "Are your cleaning products safe for homes with infants and pets?",
    "answer": "Our products are zero-VOC, plant- or mineral-derived, and EPA Design for the Environment (DfE) and Green Seal certified. Our hospital-grade disinfectant uses 0.05% thymol, a thyme extract, and kills 99.99% of bacteria and enveloped viruses on a 10-minute wet dwell. Botanical does not mean harmless, so we ask that pets and infants stay out of a room until surfaces dry.",
    "escalate_to_human": false
}"}, {"source": "CHEMICAL_SAFETY_AND_SDS_GUIDE.md", "quote": "Kettle & Loom exclusively deploys EPA Design for the Environment (DfE) and Green Seal certified cleaning chemistry: | Product / Formulation | Active Botanical Base | Target Pathogens / Soils | Dwell Time Required | | :--- | :--- | :--- | :--- | | **Bio-Shield Hospital Disinfectant** | Thymol (0.05% botanical thyme extract) | 99.99% bacteria, enveloped viruses, fungi (per label claims) | 10 minutes (wet dwell) | | **OxyPure Multi-Surface Cleaner** | Hydrogen Peroxide (stabilized 3%) | Soap scum, organic grease, protein soils | 3 minutes | | **Citrus-Loom Mineral Descaler** | Organic Citric Acid (food-grade 8%) | Hard water scale, calcium deposits, rust | 5 minutes | | **PureLoom Floor Wash** | Saponified Coconut & Olive Oil Soap | Hardwood, engineered plank, stone tiles | Immediate mop dry | *Table Summary:* [1. Approved Botanical Formulations & Active Ingredients] - Product / Formulation: Bio-Shield Hospital Disinfectant | Active Botanical Base: Thymol (0.05% botanical thyme extract) | Target Pathogens / Soils: 99.99% bacteria, enveloped viruses, fungi (per label claims) | Dwell Time Required: 10 minutes (wet dwell) - Product / Formulation: OxyPure Multi-Surface Cleaner | Active Botanical Base: Hydrogen Peroxide (stabilized 3%) | Target Pathogens / Soils: Soap scum, organic grease, protein soils | Dwell Time Required: 3 minutes - Product / Formulation: Citrus-Loom Mineral Descaler | Active Botanical Base: Organic Citric Acid (food-grade 8%) | Target Pathogens / Soils: Hard water scale, calcium deposits, rust | Dwell Time Required: 5 minutes - Product / Formulation: PureLoom Floor Wash | Active Botanical Base: Saponified Coconut & Olive Oil Soap | Target Pathogens / Soils: Hardwood, engineered plank, stone tiles | Dwell Time Required: Immediate mop dry"}]

[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-ECO-005",
    "category": "Chemical Safety & Eco-Standards",
    "question": "A cleaning product got in my eye. What should I do?",
    "answer": "Flush your eye with clean water for 10 minutes with the eyelid held open, remove contact lenses if you can, and seek medical attention if irritation persists. For ingestion, rinse the mouth and call Poison Control at 1-800-222-1222. Then contact us so we can provide the SDS and file an incident report.",
    "escalate_to_human": true
}"}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-ECO-003",
    "category": "Chemical Safety & Eco-Standards",
    "question": "Why do you leave disinfectant wet for 10 minutes?",
    "answer": "Disinfectants only work if the surface stays visibly wet for the product's full contact time. For Bio-Shield that is 10 minutes. Wiping sooner reduces how many germs are killed. OxyPure needs 3 minutes and Citrus-Loom needs 5 minutes.",
    "escalate_to_human": false
}"}, {"source": "CHEMICAL_SAFETY_AND_SDS_GUIDE.md", "quote": "- **Wet dwell** means the surface stays visibly wet for the whole period. If it dries early, reapply. - Pre-clean heavy soil first, because disinfectants do not work through grease or grime. - Do not wipe Bio-Shield before 10 minutes have passed. Use a timer. - Disinfection is performed on high-touch surfaces only: toilets, handles, switches, keypads, faucets, and remotes."}]

[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-ECO-005",
    "category": "Chemical Safety & Eco-Standards",
    "question": "A cleaning product got in my eye. What should I do?",
    "answer": "Flush your eye with clean water for 10 minutes with the eyelid held open, remove contact lenses if you can, and seek medical attention if irritation persists. For ingestion, rinse the mouth and call Poison Control at 1-800-222-1222. Then contact us so we can provide the SDS and file an incident report.",
    "escalate_to_human": true
}"}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-ECO-003",
    "category": "Chemical Safety & Eco-Standards",
    "question": "Why do you leave disinfectant wet for 10 minutes?",
    "answer": "Disinfectants only work if the surface stays visibly wet for the product's full contact time. For Bio-Shield that is 10 minutes. Wiping sooner reduces how many germs are killed. OxyPure needs 3 minutes and Citrus-Loom needs 5 minutes.",
    "escalate_to_human": false
}"}, {"source": "CHEMICAL_SAFETY_AND_SDS_GUIDE.md", "quote": "Every product has a Safety Data Sheet (SDS) in the technician binder and the mobile app, readable offline. | Exposure | Response | | :--- | :--- | | **Inhalation** | Low-hazard, zero-VOC formulations. Move to fresh air if anyone has irritation and ventilate the room. Seek medical attention if symptoms last more than 15 minutes. | | **Eye Contact** | In case of direct splash, flush eyes with potable water for **10 minutes**, holding the eyelids open. Remove contact lenses if easy to do. Seek medical attention if irritation continues. | | **Skin Contact** | Rinse with water for **5 minutes**. Remove contaminated clothing. Seek medical advice if redness persists. | | **Ingestion** | Rinse mouth. Do not induce vomiting. Call Poison Control at **1-800-222-1222** (U.S.) and follow their directions. | *Table Summary:* [3. SDS Exposure Protocols & First Aid] - Exposure: Inhalation | Response: Low-hazard, zero-VOC formulations. Move to fresh air if anyone has irritation and ventilate the room. Seek medical attention if symptoms last more than 15 minutes. - Exposure: Eye Contact | Response: In case of direct splash, flush eyes with potable water for 10 minutes, holding the eyelids open. Remove contact lenses if easy to do. Seek medical attention if irritation continues. - Exposure: Skin Contact | Response: Rinse with water for 5 minutes. Remove contaminated clothing. Seek medical advice if redness persists. - Exposure: Ingestion | Response: Rinse mouth. Do not induce vomiting. Call Poison Control at 1-800-222-1222 (U.S.) and follow their directions. **Note:** Concentrated 3% hydrogen peroxide and 8% citric acid can irritate eyes and skin. Wear nitrile gloves and eye protection when pouring or diluting concentrates."}]

[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-SCP-005",
    "category": "Scope of Services",
    "question": "Do you provide commercial office cleaning?",
    "answer": "Yes. Nightly, 3x weekly, or weekly service covering workstations, restrooms, break rooms, and common areas, at about 45 minutes per 1,000 sq ft per technician. Our technicians are W-2 employees of the cooperative, so you see the same familiar faces.",
    "escalate_to_human": false
}"}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-ACC-004",
    "category": "Property Access & Security",
    "question": "Do I need to put my dog away during cleaning?",
    "answer": "Yes. For technician safety and to prevent pets from darting out exterior doors, dogs and cats must be secured in a designated room or crate, unless we've confirmed other arrangements in writing. A technician may decline to enter if a dog is not secured, and the visit is treated as a lockout.",
    "escalate_to_human": false
}"}, {"source": "WALKTHROUGH_AND_INTAKE_SOP.md", "quote": "| Item | Recorded | | :--- | :--- | | Square footage by room | Yes | | Floor types by room | Yes | | Sensitive surfaces | Yes | | Pre-existing damage (photo log) | Yes | | Pets, infants, allergies | Yes | | Access method and alarm details | Yes (encrypted) | | Parking and loading | Yes | | Water and power access | Yes | | Client-supplied cleaning products | Note: not used unless approved | *Table Summary:* [3. Walkthrough Checklist] - Item: Square footage by room | Recorded: Yes - Item: Floor types by room | Recorded: Yes - Item: Sensitive surfaces | Recorded: Yes - Item: Pre-existing damage (photo log) | Recorded: Yes - Item: Pets, infants, allergies | Recorded: Yes - Item: Access method and alarm details | Recorded: Yes (encrypted) - Item: Parking and loading | Recorded: Yes - Item: Water and power access | Recorded: Yes - Item: Client-supplied cleaning products | Recorded: Note: not used unless approved"}, {"source": "POST_CONSTRUCTION_REMEDIATION_GUIDE.md", "quote": "Post-construction cleaning requires a sequential three-phase approach to capture settling airborne drywall gypsum and sawdust: 1. **Phase 1: Rough Debris Pass:** Removal of construction packaging, protective films, tape residue, and rough floor sweeping with HEPA capture. 2. **Phase 2: High-to-Low HEPA Vacuuming:** Dry particle extraction starting from ceiling joists, HVAC diffusers, door casings, down to baseboards. 3. **Phase 3: Wet Microfiber Sparkle Pass:** Multi-bucket damp wipe using electrostatic microfiber cloths to capture remaining microscopic dust films."}]

[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-CAN-001",
    "category": "Booking & Cancellations",
    "question": "What happens if I need to cancel my cleaning appointment tomorrow?",
    "answer": "Appointments canceled with less than 24 hours notice are subject to a 100% service fee charge because our collective members are paid for their booked time. If canceled between 24 and 48 hours in advance, a $50 administrative fee applies. Cancellations with over 48 hours notice are completely free.",
    "escalate_to_human": true
}"}, {"source": "PROPERTY_ACCESS_AND_CANCELLATION_POLICY.md", "quote": "* **48-Hour Free Cancellation:** Services may be canceled or rescheduled without penalty up to **48 hours** prior to the scheduled arrival window. * **Late Cancellation (Within 24–48 Hours):** Incurs a **$50.00 administrative rescheduling fee**. * **Same-Day Cancellation / Lockout (Under 24 Hours):** Charged at **100% of the scheduled service fee**. Our collective technicians are scheduled and paid for their booked time. | Notice Given | Fee | | :--- | :--- | | More than 48 hours | $0.00 | | 24 to 48 hours | $50.00 | | Under 24 hours | 100% of scheduled service fee | | Lockout on arrival | 100% of scheduled service fee | *Table Summary:* [2. Cancellation & Rescheduling Cutoff Schedules] - Notice Given: More than 48 hours | Fee: $0.00 - Notice Given: 24 to 48 hours | Fee: $50.00 - Notice Given: Under 24 hours | Fee: 100% of scheduled service fee - Notice Given: Lockout on arrival | Fee: 100% of scheduled service fee **Cancellation Details** - Notice is counted from the start of your scheduled arrival window. - Cancel through the client portal, by phone, or by email. Messages received after business hours (6:00 PM) count as received the next business morning. - **Weather & Emergencies:** If unsafe travel conditions or a documented emergency prevent service, we reschedule without a fee. - **Short-Term Rental Turnovers:** Cancellations of a turnover tied to a booking that was itself canceled by a guest are free when notified within 24 hours of the guest's cancellation."}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-CAN-005",
    "category": "Booking & Cancellations",
    "question": "What if bad weather stops the technicians from arriving?",
    "answer": "If unsafe travel conditions or a documented emergency prevent service, we reschedule at no charge.",
    "escalate_to_human": false
}"}, {"source": "PROPERTY_ACCESS_AND_CANCELLATION_POLICY.md", "quote": "A lockout occurs when technicians cannot enter the property within **20 minutes** of the start of the arrival window because of an incorrect code, a missing key, a deactivated PIN, or a locked interior door. - The technician tries the client's contact numbers and waits up to 20 minutes. - If entry is still not possible, the visit is recorded as a lockout and billed at **100% of the scheduled service fee**. - A one-time free rebooking is not offered for lockouts, but we are glad to help get the next visit set up. - Lockouts due to a building-management error are reviewed on a case-by-case basis."}]

[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-SCP-005",
    "category": "Scope of Services",
    "question": "Do you provide commercial office cleaning?",
    "answer": "Yes. Nightly, 3x weekly, or weekly service covering workstations, restrooms, break rooms, and common areas, at about 45 minutes per 1,000 sq ft per technician. Our technicians are W-2 employees of the cooperative, so you see the same familiar faces.",
    "escalate_to_human": false
}"}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-SCP-003",
    "category": "Scope of Services",
    "question": "Do you clean short-term rentals between guests?",
    "answer": "Yes. Our turnover service takes about 110 minutes per 1,000 sq ft per technician and includes laundering linens with hypoallergenic wash, hotel-standard bed making, restocking amenities, sanitizing high-touch surfaces, and checking for left-behind property, with photos sent when finished.",
    "escalate_to_human": false
}"}, {"source": "POST_CONSTRUCTION_REMEDIATION_GUIDE.md", "quote": "* **Equipment Standard:** Commercial HEPA vacuums certified to capture **99.97% of particulates down to 0.3 microns**. Certification labels must be on the machine, and filters are inspected before every project. * **Filter Maintenance:** Replace or clean HEPA filters when the indicator shows full, or at least every **40 hours** of use. Empty bags and canisters outdoors or into a sealed bag at the end of every shift, away from the work area. * **Air Scrubbers:** For projects with heavy dust, place a HEPA air scrubber (rated at 4+ air changes per hour for the room volume) in the room during Phase 2, and keep it running for 4 hours afterward. * **Microfiber Fold Technique:** Microfiber cloths must be folded into **8 clean quadrants** and flipped continuously to prevent spreading dry drywall dust across painted walls. - When all 8 quadrants are soiled, the cloth goes in the used pile. Never dip a used cloth back in the clean solution. - Use the multi-bucket system: one bucket of clean solution, one of rinse, and fresh cloths from a clean stack. - Use **damp**, not wet, cloths, wrung out so that no water drips. Wet cloths turn drywall dust into a paste. * **Surface Cleaner:** OxyPure, diluted to label, or plain water on delicate finishes. See `CHEMICAL_SAFETY_AND_SDS_GUIDE.md`."}, {"source": "PROPERTY_ACCESS_AND_CANCELLATION_POLICY.md", "quote": "We love pets, but for technician safety and to prevent pets from darting out exterior doors, dogs and cats must be secured in a designated room or crate during service unless prior written arrangements are confirmed. - Mark the room with a sign, and make sure the room has water. - Tell us about any pets that bite, escape, or react to strangers when you book. - Technicians may decline to enter a property where a dog is not secured, and the visit is treated as a lockout. - Exotic pets, reptiles, and aquariums are not touched or cleaned. - Pets must not be left in spaces with wet floors."}]

[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-ACC-005",
    "category": "Property Access & Security",
    "question": "Something in my home was damaged during a cleaning. What now?",
    "answer": "Report it within 24 hours with photos. We maintain liability insurance and bonding, and claims are reviewed within 5 business days. We will compare against the pre-existing condition photos taken at your walkthrough.",
    "escalate_to_human": true
}"}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-SCP-001",
    "category": "Scope of Services",
    "question": "Do you clean unsealed marble or antique wood furniture?",
    "answer": "During your initial walkthrough, our team maps all sensitive surfaces. We use pH-neutral saponified soap washes for hardwood and unsealed stone. We strictly prohibit the use of acidic descalers on marble, limestone, or terrazzo to prevent etching.",
    "escalate_to_human": false
}"}, {"source": "WALKTHROUGH_AND_INTAKE_SOP.md", "quote": "Photos are used only to document condition and are stored in the client's secured profile. They are deleted 90 days after the contract ends, unless a dispute is open."}, {"source": "POST_CONSTRUCTION_REMEDIATION_GUIDE.md", "quote": "| Stage | Timing | | :--- | :--- | | Rough clean (Phase 1) | After trade work, before final painting touch-ups | | Final clean (Phases 2–3) | After all trades are done, no earlier than 24–48 hours after last sanding | | Touch-up visit | Within 7 days of the final clean, if needed | *Table Summary:* [5. Scheduling] - Stage: Rough clean (Phase 1) | Timing: After trade work, before final painting touch-ups - Stage: Final clean (Phases 2–3) | Timing: After all trades are done, no earlier than 24–48 hours after last sanding - Stage: Touch-up visit | Timing: Within 7 days of the final clean, if needed Dust can resettle for several days after finishing, which is why a short touch-up visit is offered."}]

[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-PST-001",
    "category": "Post-Construction Services",
    "question": "Why does post-construction cleaning require multiple passes?",
    "answer": "Drywall and sawdust particles remain suspended in the air for up to 48 hours after construction wraps up. We utilize certified 0.3-micron HEPA vacuums and a structured three-phase process (rough pass, deep vacuum, damp microfiber sparkle wipe) to prevent settling dust from coating surfaces after cleaning.",
    "escalate_to_human": false
}"}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-PST-005",
    "category": "Post-Construction Services",
    "question": "Dust came back a few days after you cleaned. Can you return?",
    "answer": "Fine dust can resettle for several days after finishing. We offer a touch-up visit within 7 days of the final clean, and will walk the punch list with you or your contractor within 48 hours.",
    "escalate_to_human": true
}"}, {"source": "POST_CONSTRUCTION_REMEDIATION_GUIDE.md", "quote": "Post-construction cleaning requires a sequential three-phase approach to capture settling airborne drywall gypsum and sawdust: 1. **Phase 1: Rough Debris Pass:** Removal of construction packaging, protective films, tape residue, and rough floor sweeping with HEPA capture. 2. **Phase 2: High-to-Low HEPA Vacuuming:** Dry particle extraction starting from ceiling joists, HVAC diffusers, door casings, down to baseboards. 3. **Phase 3: Wet Microfiber Sparkle Pass:** Multi-bucket damp wipe using electrostatic microfiber cloths to capture remaining microscopic dust films."}, {"source": "POST_CONSTRUCTION_REMEDIATION_GUIDE.md", "quote": "**Kettle & Loom Cleaning Collective** — *Pure Ingredients. Meticulous Spaces. Uncompromising Clean.* Construction dust is fine, clings to surfaces, and is easily disturbed. Drywall gypsum, sawdust, and, in some cases, crystalline silica (from cutting concrete, tile, or masonry) require a methodical, top-to-bottom process."}]

