[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-PST-005",
    "category": "Post-Construction Services",
    "question": "Dust came back a few days after you cleaned. Can you return?",
    "answer": "Fine dust can resettle for several days after finishing. We offer a touch-up visit within 7 days of the final clean, and will walk the punch list with you or your contractor within 48 hours.",
    "escalate_to_human": true
}"}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-PST-001",
    "category": "Post-Construction Services",
    "question": "Why does post-construction cleaning require multiple passes?",
    "answer": "Drywall and sawdust particles remain suspended in the air for up to 48 hours after construction wraps up. We utilize certified 0.3-micron HEPA vacuums and a structured three-phase process (rough pass, deep vacuum, damp microfiber sparkle wipe) to prevent settling dust from coating surfaces after cleaning.",
    "escalate_to_human": false
}"}, {"source": "POST_CONSTRUCTION_REMEDIATION_GUIDE.md", "quote": "| Stage | Timing | | :--- | :--- | | Rough clean (Phase 1) | After trade work, before final painting touch-ups | | Final clean (Phases 2–3) | After all trades are done, no earlier than 24–48 hours after last sanding | | Touch-up visit | Within 7 days of the final clean, if needed | *Table Summary:* [5. Scheduling] - Stage: Rough clean (Phase 1) | Timing: After trade work, before final painting touch-ups - Stage: Final clean (Phases 2–3) | Timing: After all trades are done, no earlier than 24–48 hours after last sanding - Stage: Touch-up visit | Timing: Within 7 days of the final clean, if needed Dust can resettle for several days after finishing, which is why a short touch-up visit is offered."}, {"source": "POST_CONSTRUCTION_REMEDIATION_GUIDE.md", "quote": "Post-construction cleaning requires a sequential three-phase approach to capture settling airborne drywall gypsum and sawdust: 1. **Phase 1: Rough Debris Pass:** Removal of construction packaging, protective films, tape residue, and rough floor sweeping with HEPA capture. 2. **Phase 2: High-to-Low HEPA Vacuuming:** Dry particle extraction starting from ceiling joists, HVAC diffusers, door casings, down to baseboards. 3. **Phase 3: Wet Microfiber Sparkle Pass:** Multi-bucket damp wipe using electrostatic microfiber cloths to capture remaining microscopic dust films."}]

[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-CAN-004",
    "category": "Booking & Cancellations",
    "question": "How do you price a cleaning?",
    "answer": "Estimates use our scope matrix and a base rate of $55.00 per technician-hour. Maintenance cleans take about 75 minutes per 1,000 sq ft, short-term rental turnovers about 110 minutes, and commercial offices about 45 minutes. You receive a fixed-price proposal after your 30-minute walkthrough.",
    "escalate_to_human": false
}"}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-PST-003",
    "category": "Post-Construction Services",
    "question": "How long does a post-construction clean take?",
    "answer": "About 240 technician-minutes per 1,000 sq ft across all three phases. That is roughly 20% rough debris, 40% HEPA vacuuming, and 40% wet microfiber. A 2,000 sq ft home takes about 8 technician-hours, spread over two visits so dust can settle.",
    "escalate_to_human": false
}"}, {"source": "WALKTHROUGH_AND_INTAKE_SOP.md", "quote": "All recurring service contracts must undergo a foundational **Initial Deep Clean**. This baseline visit removes pre-existing buildup, limescale, and synthetic wax residues from previous chemical cleaners before beginning botanical maintenance. - **Duration:** Typically **2.0x to 2.5x** the standard maintenance time for the same square footage (for example, a 2,000 sq ft home that takes 150 minutes for maintenance will take about 5 to 6.25 hours of technician time for the deep clean). - **Added Tasks:** Interior oven and refrigerator, baseboards, door casings, window sills and tracks, cabinet interiors on request, descaling of fixtures, and detailed grout work. - **Why It Is Mandatory:** Botanical chemistry cannot lift old synthetic residues on its own, and the baseline sets a measurable standard for every visit after it. - **Short-Term Rental Properties:** A baseline deep clean is required before the first turnover. - **Pricing:** Quoted as a fixed price at the walkthrough. Rates are not charged beyond the quote unless conditions differ from the photos, and the client approves any change first."}]

