[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-PST-004",
    "category": "Post-Construction Services",
    "question": "Can you clean up silica dust from cutting tile or concrete?",
    "answer": "We use wet methods and HEPA only, with proper respirators, and never dry sweep. Large silica contamination or suspected asbestos or lead should be assessed by a certified abatement contractor, so please call us before work begins.",
    "escalate_to_human": true
}"}, {"source": "POST_CONSTRUCTION_REMEDIATION_GUIDE.md", "quote": "- **Respiratory protection:** NIOSH-approved N95 at minimum, and a P100 half-face respirator when silica may be present. - **Eye protection and gloves** are always worn. Disposable coveralls are used for heavy dust. - **Silica:** Where crystalline silica from cutting stone, concrete, or tile is a concern, work is limited to wet methods and HEPA only. Do not dry sweep. Follow OSHA's respirable crystalline silica standard. - **Hydration and breaks:** 10-minute break every 90 minutes in dusty areas. - Our technicians are not trained for asbestos or lead abatement. If suspected materials are found, work stops in that area, and the client is informed."}, {"source": "POST_CONSTRUCTION_REMEDIATION_GUIDE.md", "quote": "**Kettle & Loom Cleaning Collective** — *Pure Ingredients. Meticulous Spaces. Uncompromising Clean.* Construction dust is fine, clings to surfaces, and is easily disturbed. Drywall gypsum, sawdust, and, in some cases, crystalline silica (from cutting concrete, tile, or masonry) require a methodical, top-to-bottom process."}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-PST-005",
    "category": "Post-Construction Services",
    "question": "Dust came back a few days after you cleaned. Can you return?",
    "answer": "Fine dust can resettle for several days after finishing. We offer a touch-up visit within 7 days of the final clean, and will walk the punch list with you or your contractor within 48 hours.",
    "escalate_to_human": true
}"}]

[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-ACC-002",
    "category": "Property Access & Security",
    "question": "How do you handle my keys and door codes?",
    "answer": "A smart lock with a unique service PIN is preferred. If you use physical keys, they stay in an on-site lockbox, and technicians never carry permanent property keys off-site. Alarm and access codes are stored in encrypted profiles.",
    "escalate_to_human": false
}"}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-ACC-001",
    "category": "Property Access & Security",
    "question": "Do I need to be home when the cleaning collective arrives?",
    "answer": "No. Most residential and commercial clients provide a smart lock code or lockbox key. Our technicians arrive within the designated arrival window, complete the service scope, re-secure all windows and doors, and set the security alarm upon departure.",
    "escalate_to_human": false
}"}, {"source": "PROPERTY_ACCESS_AND_CANCELLATION_POLICY.md", "quote": "* **Digital Keypads & Smart Locks:** Preferred access method. Clients provide a unique service PIN designated exclusively for Kettle & Loom staff. We recommend a PIN that is active only during the service window. * **Physical Lockboxes:** If using physical keys, keys must remain inside a secure on-site lockbox. Technicians will not carry permanent property keys off-site. Lockbox codes are shared only with the assigned team and changed on request. * **Alarm Systems:** Alarm disarm codes and re-arming instructions must be stored in encrypted client profiles. Any false alarm dispatch fees resulting from inaccurate client codes are the client's responsibility. - Technicians disarm on arrival and re-arm on departure. If an alarm triggers, the technician calls the client and the alarm company within **5 minutes** and gives the correct passcode. - Provide your alarm company's name and the verbal passcode for dispatch. * **Departure Procedure:** Technicians re-lock all doors, close windows, set the thermostat to its original setting, turn off lights, and text a completion notice. * **Key Custody:** Access details are visible only to the Operations team and the assigned technicians. Access codes are removed from the technician's device when the contract ends. * **Garage and Gate Codes:** Provide any gate, garage, or elevator access in your profile."}, {"source": "PROPERTY_ACCESS_AND_CANCELLATION_POLICY.md", "quote": "We love pets, but for technician safety and to prevent pets from darting out exterior doors, dogs and cats must be secured in a designated room or crate during service unless prior written arrangements are confirmed. - Mark the room with a sign, and make sure the room has water. - Tell us about any pets that bite, escape, or react to strangers when you book. - Technicians may decline to enter a property where a dog is not secured, and the visit is treated as a lockout. - Exotic pets, reptiles, and aquariums are not touched or cleaned. - Pets must not be left in spaces with wet floors."}]

[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-ECO-005",
    "category": "Chemical Safety & Eco-Standards",
    "question": "A cleaning product got in my eye. What should I do?",
    "answer": "Flush your eye with clean water for 10 minutes with the eyelid held open, remove contact lenses if you can, and seek medical attention if irritation persists. For ingestion, rinse the mouth and call Poison Control at 1-800-222-1222. Then contact us so we can provide the SDS and file an incident report.",
    "escalate_to_human": true
}"}, {"source": "CHEMICAL_SAFETY_AND_SDS_GUIDE.md", "quote": "Every product has a Safety Data Sheet (SDS) in the technician binder and the mobile app, readable offline. | Exposure | Response | | :--- | :--- | | **Inhalation** | Low-hazard, zero-VOC formulations. Move to fresh air if anyone has irritation and ventilate the room. Seek medical attention if symptoms last more than 15 minutes. | | **Eye Contact** | In case of direct splash, flush eyes with potable water for **10 minutes**, holding the eyelids open. Remove contact lenses if easy to do. Seek medical attention if irritation continues. | | **Skin Contact** | Rinse with water for **5 minutes**. Remove contaminated clothing. Seek medical advice if redness persists. | | **Ingestion** | Rinse mouth. Do not induce vomiting. Call Poison Control at **1-800-222-1222** (U.S.) and follow their directions. | *Table Summary:* [3. SDS Exposure Protocols & First Aid] - Exposure: Inhalation | Response: Low-hazard, zero-VOC formulations. Move to fresh air if anyone has irritation and ventilate the room. Seek medical attention if symptoms last more than 15 minutes. - Exposure: Eye Contact | Response: In case of direct splash, flush eyes with potable water for 10 minutes, holding the eyelids open. Remove contact lenses if easy to do. Seek medical attention if irritation continues. - Exposure: Skin Contact | Response: Rinse with water for 5 minutes. Remove contaminated clothing. Seek medical advice if redness persists. - Exposure: Ingestion | Response: Rinse mouth. Do not induce vomiting. Call Poison Control at 1-800-222-1222 (U.S.) and follow their directions. **Note:** Concentrated 3% hydrogen peroxide and 8% citric acid can irritate eyes and skin. Wear nitrile gloves and eye protection when pouring or diluting concentrates."}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-SCP-004",
    "category": "Scope of Services",
    "question": "Is there anything you won't clean?",
    "answer": "We do not handle biohazards, mold remediation, or asbestos and lead abatement, and we don't move furniture over 50 lb. We also do not use acid on unsealed natural stone.",
    "escalate_to_human": false
}"}]

[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-CAN-001",
    "category": "Booking & Cancellations",
    "question": "What happens if I need to cancel my cleaning appointment tomorrow?",
    "answer": "Appointments canceled with less than 24 hours notice are subject to a 100% service fee charge because our collective members are paid for their booked time. If canceled between 24 and 48 hours in advance, a $50 administrative fee applies. Cancellations with over 48 hours notice are completely free.",
    "escalate_to_human": true
}"}, {"source": "PROPERTY_ACCESS_AND_CANCELLATION_POLICY.md", "quote": "* **48-Hour Free Cancellation:** Services may be canceled or rescheduled without penalty up to **48 hours** prior to the scheduled arrival window. * **Late Cancellation (Within 24–48 Hours):** Incurs a **$50.00 administrative rescheduling fee**. * **Same-Day Cancellation / Lockout (Under 24 Hours):** Charged at **100% of the scheduled service fee**. Our collective technicians are scheduled and paid for their booked time. | Notice Given | Fee | | :--- | :--- | | More than 48 hours | $0.00 | | 24 to 48 hours | $50.00 | | Under 24 hours | 100% of scheduled service fee | | Lockout on arrival | 100% of scheduled service fee | *Table Summary:* [2. Cancellation & Rescheduling Cutoff Schedules] - Notice Given: More than 48 hours | Fee: $0.00 - Notice Given: 24 to 48 hours | Fee: $50.00 - Notice Given: Under 24 hours | Fee: 100% of scheduled service fee - Notice Given: Lockout on arrival | Fee: 100% of scheduled service fee **Cancellation Details** - Notice is counted from the start of your scheduled arrival window. - Cancel through the client portal, by phone, or by email. Messages received after business hours (6:00 PM) count as received the next business morning. - **Weather & Emergencies:** If unsafe travel conditions or a documented emergency prevent service, we reschedule without a fee. - **Short-Term Rental Turnovers:** Cancellations of a turnover tied to a booking that was itself canceled by a guest are free when notified within 24 hours of the guest's cancellation."}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-CAN-002",
    "category": "Booking & Cancellations",
    "question": "What is a lockout and what does it cost?",
    "answer": "A lockout means we can't enter within 20 minutes of the start of the arrival window, for example because of a wrong code or a missing key. It is billed at 100% of the scheduled service fee.",
    "escalate_to_human": true
}"}, {"source": "PROPERTY_ACCESS_AND_CANCELLATION_POLICY.md", "quote": "A lockout occurs when technicians cannot enter the property within **20 minutes** of the start of the arrival window because of an incorrect code, a missing key, a deactivated PIN, or a locked interior door. - The technician tries the client's contact numbers and waits up to 20 minutes. - If entry is still not possible, the visit is recorded as a lockout and billed at **100% of the scheduled service fee**. - A one-time free rebooking is not offered for lockouts, but we are glad to help get the next visit set up. - Lockouts due to a building-management error are reviewed on a case-by-case basis."}]

[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-PST-003",
    "category": "Post-Construction Services",
    "question": "How long does a post-construction clean take?",
    "answer": "About 240 technician-minutes per 1,000 sq ft across all three phases. That is roughly 20% rough debris, 40% HEPA vacuuming, and 40% wet microfiber. A 2,000 sq ft home takes about 8 technician-hours, spread over two visits so dust can settle.",
    "escalate_to_human": false
}"}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-CAN-004",
    "category": "Booking & Cancellations",
    "question": "How do you price a cleaning?",
    "answer": "Estimates use our scope matrix and a base rate of $55.00 per technician-hour. Maintenance cleans take about 75 minutes per 1,000 sq ft, short-term rental turnovers about 110 minutes, and commercial offices about 45 minutes. You receive a fixed-price proposal after your 30-minute walkthrough.",
    "escalate_to_human": false
}"}, {"source": "service_scope_matrix.json", "quote": "{
    "tier_id": "TIER-PCN-04",
    "tier_name": "Post-Construction Remediation",
    "frequency_options": [
        "One-time (three phases)",
        "Touch-up visit within 7 days"
    ],
    "requires_initial_deep_clean": false,
    "zones": {
        "phase_1_rough_debris_pass": [
            "Remove construction packaging, protective films, stickers, and tape residue",
            "Scrape paint splatter with plastic blades",
            "Rough sweep floors with HEPA capture"
        ],
        "phase_2_high_to_low_hepa_vacuuming": [
            "HEPA vacuum ceiling joists, fans, HVAC diffusers, and light fixtures",
            "HEPA vacuum door casings, window tracks, and cabinet tops",
            "HEPA vacuum baseboards and floors (99.97% at 0.3 microns)"
        ],
        "phase_3_wet_microfiber_sparkle_pass": [
            "Damp wipe all surfaces with 8-quadrant folded microfiber",
            "Clean cabinet interiors, glass, and fixtures",
            "Final HEPA vacuum and white-glove inspection (3 sample points per room)"
        ]
    },
    "phase_labor_share_percent": {
        "phase_1": 20,
        "phase_2": 40,
        "phase_3": 40
    },
    "estimated_minutes_per_1000_sqft": 240
}"}, {"source": "POST_CONSTRUCTION_REMEDIATION_GUIDE.md", "quote": "Post-construction cleaning requires a sequential three-phase approach to capture settling airborne drywall gypsum and sawdust: 1. **Phase 1: Rough Debris Pass:** Removal of construction packaging, protective films, tape residue, and rough floor sweeping with HEPA capture. 2. **Phase 2: High-to-Low HEPA Vacuuming:** Dry particle extraction starting from ceiling joists, HVAC diffusers, door casings, down to baseboards. 3. **Phase 3: Wet Microfiber Sparkle Pass:** Multi-bucket damp wipe using electrostatic microfiber cloths to capture remaining microscopic dust films."}]

[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-CAN-001",
    "category": "Booking & Cancellations",
    "question": "What happens if I need to cancel my cleaning appointment tomorrow?",
    "answer": "Appointments canceled with less than 24 hours notice are subject to a 100% service fee charge because our collective members are paid for their booked time. If canceled between 24 and 48 hours in advance, a $50 administrative fee applies. Cancellations with over 48 hours notice are completely free.",
    "escalate_to_human": true
}"}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-CAN-003",
    "category": "Booking & Cancellations",
    "question": "Do I have to pay an initial deep clean?",
    "answer": "Yes, all recurring contracts start with a foundational Initial Deep Clean. It removes buildup, limescale, and synthetic wax residue from earlier cleaners, and typically takes 2.0 to 2.5 times a regular visit. It is quoted as a fixed price during your walkthrough.",
    "escalate_to_human": false
}"}, {"source": "WALKTHROUGH_AND_INTAKE_SOP.md", "quote": "1. **Initial Property Audit:** Conduct a **30-minute** on-site assessment with the client or property manager. Measure and record the square footage of each room and total conditioned space, and note the number of bedrooms, bathrooms, and floor types. Confirm that the square footage on the booking is within 10% of the measured figure. 2. **Surface Sensitivity Mapping:** Log all sensitive materials (honed Carrara marble, unsealed butcher block, oil-rubbed bronze hardware, wool area rugs). Each entry has the room, material, and the approved product (see `CHEMICAL_SAFETY_AND_SDS_GUIDE.md`). 3. **Pre-Existing Condition Documentation:** Photograph existing carpet stains, scratched wood floors, and chipped tiles. Upload to the client profile with a date stamp. Take at least **3 photos per room** (wide shot plus close-ups), and a photo of each existing defect with a coin or ruler for scale. 4. **Air Quality & Allergen Assessment:** Identify presence of pets, dust sensitivities, or fragrance allergies to tailor hypoallergenic essential oils or go fully unscented. 5. **Estimate & Scope Confirmation:** Generate a fixed-price proposal detailing initial deep-clean baseline hours and ongoing maintenance frequencies. The estimate uses `service_scope_matrix.json` and a base rate of $55.00 per technician-hour. **Output:** A signed Property Profile containing the sensitivity map, photo log, access and alarm details (stored encrypted), pet details, and scope."}]

[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-ECO-002",
    "category": "Chemical Safety & Eco-Standards",
    "question": "What ingredients do you use?",
    "answer": "Bio-Shield Disinfectant uses 0.05% thymol, OxyPure uses stabilized 3% hydrogen peroxide, Citrus-Loom Descaler uses 8% food-grade citric acid, and PureLoom Floor Wash is a saponified coconut and olive oil soap. We provide Safety Data Sheets for every product on request.",
    "escalate_to_human": false
}"}, {"source": "CHEMICAL_SAFETY_AND_SDS_GUIDE.md", "quote": "* **Strict Acid Prohibition:** *Citrus-Loom Descaler and acidic solutions must NEVER be applied to unsealed natural marble, travertine, limestone, or terrazzo.* Acid etching permanently damages calcite stone. * **Hardwood Neutrality:** Wood flooring must be cleaned exclusively with pH-neutral PureLoom wash. Never saturate it with standing water. * **Granite & Quartz:** Use OxyPure only. No descaler on sealed stone unless the sealer is confirmed intact and the surface is rinsed within 5 minutes. * **Oil-Rubbed Bronze & Unlacquered Brass:** Dry microfiber only. No acids or peroxide, as they strip the finish. * **Unsealed Butcher Block:** Damp wipe with PureLoom diluted to the label ratio. Do not apply disinfectant to unsealed wood for a full dwell time. * **Wool Rugs & Natural Fibers:** Do not apply hydrogen peroxide, because it may bleach dyed fibers. Spot test first in a hidden area. Always check the client's Surface Sensitivity Map (see `WALKTHROUGH_AND_INTAKE_SOP.md`) before opening a product."}, {"source": "CHEMICAL_SAFETY_AND_SDS_GUIDE.md", "quote": "- **Never mix** products with one another. Never combine hydrogen peroxide with vinegar or other acids, because they form peracetic acid, an irritant. - **Never** mix with chlorine bleach or ammonia brought by a client. - Dilute concentrates only with the metered dispensers, using room-temperature water (60°F–80°F / 16°C–27°C). Hot water above 120°F (49°C) degrades hydrogen peroxide and thymol. - Use fresh dilutions. Discard unused mixed solutions after **7 days**."}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-SCP-001",
    "category": "Scope of Services",
    "question": "Do you clean unsealed marble or antique wood furniture?",
    "answer": "During your initial walkthrough, our team maps all sensitive surfaces. We use pH-neutral saponified soap washes for hardwood and unsealed stone. We strictly prohibit the use of acidic descalers on marble, limestone, or terrazzo to prevent etching.",
    "escalate_to_human": false
}"}]

[{"source": "POST_CONSTRUCTION_REMEDIATION_GUIDE.md", "quote": "Post-construction cleaning requires a sequential three-phase approach to capture settling airborne drywall gypsum and sawdust: 1. **Phase 1: Rough Debris Pass:** Removal of construction packaging, protective films, tape residue, and rough floor sweeping with HEPA capture. 2. **Phase 2: High-to-Low HEPA Vacuuming:** Dry particle extraction starting from ceiling joists, HVAC diffusers, door casings, down to baseboards. 3. **Phase 3: Wet Microfiber Sparkle Pass:** Multi-bucket damp wipe using electrostatic microfiber cloths to capture remaining microscopic dust films."}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-PST-001",
    "category": "Post-Construction Services",
    "question": "Why does post-construction cleaning require multiple passes?",
    "answer": "Drywall and sawdust particles remain suspended in the air for up to 48 hours after construction wraps up. We utilize certified 0.3-micron HEPA vacuums and a structured three-phase process (rough pass, deep vacuum, damp microfiber sparkle wipe) to prevent settling dust from coating surfaces after cleaning.",
    "escalate_to_human": false
}"}, {"source": "POST_CONSTRUCTION_REMEDIATION_GUIDE.md", "quote": "* **Equipment Standard:** Commercial HEPA vacuums certified to capture **99.97% of particulates down to 0.3 microns**. Certification labels must be on the machine, and filters are inspected before every project. * **Filter Maintenance:** Replace or clean HEPA filters when the indicator shows full, or at least every **40 hours** of use. Empty bags and canisters outdoors or into a sealed bag at the end of every shift, away from the work area. * **Air Scrubbers:** For projects with heavy dust, place a HEPA air scrubber (rated at 4+ air changes per hour for the room volume) in the room during Phase 2, and keep it running for 4 hours afterward. * **Microfiber Fold Technique:** Microfiber cloths must be folded into **8 clean quadrants** and flipped continuously to prevent spreading dry drywall dust across painted walls. - When all 8 quadrants are soiled, the cloth goes in the used pile. Never dip a used cloth back in the clean solution. - Use the multi-bucket system: one bucket of clean solution, one of rinse, and fresh cloths from a clean stack. - Use **damp**, not wet, cloths, wrung out so that no water drips. Wet cloths turn drywall dust into a paste. * **Surface Cleaner:** OxyPure, diluted to label, or plain water on delicate finishes. See `CHEMICAL_SAFETY_AND_SDS_GUIDE.md`."}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-PST-004",
    "category": "Post-Construction Services",
    "question": "Can you clean up silica dust from cutting tile or concrete?",
    "answer": "We use wet methods and HEPA only, with proper respirators, and never dry sweep. Large silica contamination or suspected asbestos or lead should be assessed by a certified abatement contractor, so please call us before work begins.",
    "escalate_to_human": true
}"}]

