[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-SCP-002",
    "category": "Scope of Services",
    "question": "What does a standard residential clean include?",
    "answer": "Kitchen: cabinet faces, countertops, stainless exteriors, sink, and floors. Bathrooms: grout, tubs, toilets, mirrors, and fixtures. Plus dusting, HEPA vacuuming, and damp mopping in living areas and bedrooms. Interior ovens, refrigerators, and cabinets are add-ons.",
    "escalate_to_human": false
}"}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-SCP-001",
