[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-SCP-005",
    "category": "Scope of Services",
    "question": "Do you provide commercial office cleaning?",
    "answer": "Yes. Nightly, 3x weekly, or weekly service covering workstations, restrooms, break rooms, and common areas, at about 45 minutes per 1,000 sq ft per technician. Our technicians are W-2 employees of the cooperative, so you see the same familiar faces.",
    "escalate_to_human": false
}"}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-ECO-001",
    "category": "Chemical Safety & Eco-Standards",
    "question": "Are your cleaning products safe for homes with infants and pets?",
    "answer": "Our products are zero-VOC, plant- or mineral-derived, and EPA Design for the Environment (DfE) and Green Seal certified. Our hospital-grade disinfectant uses 0.05% thymol, a thyme extract, and kills 99.99% of bacteria and enveloped viruses on a 10-minute wet dwell. Botanical does not mean harmless, so we ask that pets and infants stay out of a room until surfaces dry.",
    "escalate_to_human": false
}"}, {"source": "service_scope_matrix.json", "quote": "{
    "name": "Laundry (per load, residential or rental)",
    "estimated_minutes_each": 15
}"}, {"source": "WALKTHROUGH_AND_INTAKE_SOP.md", "quote": "| Item | Recorded | | :--- | :--- | | Square footage by room | Yes | | Floor types by room | Yes | | Sensitive surfaces | Yes | | Pre-existing damage (photo log) | Yes | | Pets, infants, allergies | Yes | | Access method and alarm details | Yes (encrypted) | | Parking and loading | Yes | | Water and power access | Yes | | Client-supplied cleaning products | Note: not used unless approved | *Table Summary:* [3. Walkthrough Checklist] - Item: Square footage by room | Recorded: Yes - Item: Floor types by room | Recorded: Yes - Item: Sensitive surfaces | Recorded: Yes - Item: Pre-existing damage (photo log) | Recorded: Yes - Item: Pets, infants, allergies | Recorded: Yes - Item: Access method and alarm details | Recorded: Yes (encrypted) - Item: Parking and loading | Recorded: Yes - Item: Water and power access | Recorded: Yes - Item: Client-supplied cleaning products | Recorded: Note: not used unless approved"}]

[{"source": "PROPERTY_ACCESS_AND_CANCELLATION_POLICY.md", "quote": "* **48-Hour Free Cancellation:** Services may be canceled or rescheduled without penalty up to **48 hours** prior to the scheduled arrival window. * **Late Cancellation (Within 24–48 Hours):** Incurs a **$50.00 administrative rescheduling fee**. * **Same-Day Cancellation / Lockout (Under 24 Hours):** Charged at **100% of the scheduled service fee**. Our collective technicians are scheduled and paid for their booked time. | Notice Given | Fee | | :--- | :--- | | More than 48 hours | $0.00 | | 24 to 48 hours | $50.00 | | Under 24 hours | 100% of scheduled service fee | | Lockout on arrival | 100% of scheduled service fee | *Table Summary:* [2. Cancellation & Rescheduling Cutoff Schedules] - Notice Given: More than 48 hours | Fee: $0.00 - Notice Given: 24 to 48 hours | Fee: $50.00 - Notice Given: Under 24 hours | Fee: 100% of scheduled service fee - Notice Given: Lockout on arrival | Fee: 100% of scheduled service fee **Cancellation Details** - Notice is counted from the start of your scheduled arrival window. - Cancel through the client portal, by phone, or by email. Messages received after business hours (6:00 PM) count as received the next business morning. - **Weather & Emergencies:** If unsafe travel conditions or a documented emergency prevent service, we reschedule without a fee. - **Short-Term Rental Turnovers:** Cancellations of a turnover tied to a booking that was itself canceled by a guest are free when notified within 24 hours of the guest's cancellation."}, {"source": "WALKTHROUGH_AND_INTAKE_SOP.md", "quote": "- The proposal is sent within **1 business day**. - Services start no sooner than 3 business days after signing, so we can schedule the same technician team. - A named lead technician is assigned. We aim to keep the same team on each visit."}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-SCP-005",
    "category": "Scope of Services",
    "question": "Do you provide commercial office cleaning?",
    "answer": "Yes. Nightly, 3x weekly, or weekly service covering workstations, restrooms, break rooms, and common areas, at about 45 minutes per 1,000 sq ft per technician. Our technicians are W-2 employees of the cooperative, so you see the same familiar faces.",
    "escalate_to_human": false
}"}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-CAN-001",
    "category": "Booking & Cancellations",
    "question": "What happens if I need to cancel my cleaning appointment tomorrow?",
    "answer": "Appointments canceled with less than 24 hours notice are subject to a 100% service fee charge because our collective members are paid for their booked time. If canceled between 24 and 48 hours in advance, a $50 administrative fee applies. Cancellations with over 48 hours notice are completely free.",
    "escalate_to_human": true
}"}]

[{"source": "POST_CONSTRUCTION_REMEDIATION_GUIDE.md", "quote": "- **White Glove Test:** A clean white microfiber cloth wiped across a horizontal surface at **3 sample locations per room** should pick up no visible dust. - **Flashlight Inspection:** A raking-light check of painted surfaces and glass at a low angle. - **Walkthrough:** The client or general contractor does a final walkthrough with the Site Lead, with a punch list completed within **48 hours**. - HVAC: Replace the system filter after the final pass. Ducts are not cleaned under this service."}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-PST-001",
    "category": "Post-Construction Services",
    "question": "Why does post-construction cleaning require multiple passes?",
    "answer": "Drywall and sawdust particles remain suspended in the air for up to 48 hours after construction wraps up. We utilize certified 0.3-micron HEPA vacuums and a structured three-phase process (rough pass, deep vacuum, damp microfiber sparkle wipe) to prevent settling dust from coating surfaces after cleaning.",
    "escalate_to_human": false
}"}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-PST-005",
    "category": "Post-Construction Services",
    "question": "Dust came back a few days after you cleaned. Can you return?",
    "answer": "Fine dust can resettle for several days after finishing. We offer a touch-up visit within 7 days of the final clean, and will walk the punch list with you or your contractor within 48 hours.",
    "escalate_to_human": true
}"}, {"source": "POST_CONSTRUCTION_REMEDIATION_GUIDE.md", "quote": "* **Equipment Standard:** Commercial HEPA vacuums certified to capture **99.97% of particulates down to 0.3 microns**. Certification labels must be on the machine, and filters are inspected before every project. * **Filter Maintenance:** Replace or clean HEPA filters when the indicator shows full, or at least every **40 hours** of use. Empty bags and canisters outdoors or into a sealed bag at the end of every shift, away from the work area. * **Air Scrubbers:** For projects with heavy dust, place a HEPA air scrubber (rated at 4+ air changes per hour for the room volume) in the room during Phase 2, and keep it running for 4 hours afterward. * **Microfiber Fold Technique:** Microfiber cloths must be folded into **8 clean quadrants** and flipped continuously to prevent spreading dry drywall dust across painted walls. - When all 8 quadrants are soiled, the cloth goes in the used pile. Never dip a used cloth back in the clean solution. - Use the multi-bucket system: one bucket of clean solution, one of rinse, and fresh cloths from a clean stack. - Use **damp**, not wet, cloths, wrung out so that no water drips. Wet cloths turn drywall dust into a paste. * **Surface Cleaner:** OxyPure, diluted to label, or plain water on delicate finishes. See `CHEMICAL_SAFETY_AND_SDS_GUIDE.md`."}]

[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-ACC-005",
    "category": "Property Access & Security",
    "question": "Something in my home was damaged during a cleaning. What now?",
    "answer": "Report it within 24 hours with photos. We maintain liability insurance and bonding, and claims are reviewed within 5 business days. We will compare against the pre-existing condition photos taken at your walkthrough.",
