[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-SCP-001",
    "category": "Scope of Services",
    "question": "Do you clean unsealed marble or antique wood furniture?",
    "answer": "During your initial walkthrough, our team maps all sensitive surfaces. We use pH-neutral saponified soap washes for hardwood and unsealed stone. We strictly prohibit the use of acidic descalers on marble, limestone, or terrazzo to prevent etching.",
    "escalate_to_human": false
}"}, {"source": "CHEMICAL_SAFETY_AND_SDS_GUIDE.md", "quote": "* **Strict Acid Prohibition:** *Citrus-Loom Descaler and acidic solutions must NEVER be applied to unsealed natural marble, travertine, limestone, or terrazzo.* Acid etching permanently damages calcite stone. * **Hardwood Neutrality:** Wood flooring must be cleaned exclusively with pH-neutral PureLoom wash. Never saturate it with standing water. * **Granite & Quartz:** Use OxyPure only. No descaler on sealed stone unless the sealer is confirmed intact and the surface is rinsed within 5 minutes. * **Oil-Rubbed Bronze & Unlacquered Brass:** Dry microfiber only. No acids or peroxide, as they strip the finish. * **Unsealed Butcher Block:** Damp wipe with PureLoom diluted to the label ratio. Do not apply disinfectant to unsealed wood for a full dwell time. * **Wool Rugs & Natural Fibers:** Do not apply hydrogen peroxide, because it may bleach dyed fibers. Spot test first in a hidden area. Always check the client's Surface Sensitivity Map (see `WALKTHROUGH_AND_INTAKE_SOP.md`) before opening a product."}, {"source": "POST_CONSTRUCTION_REMEDIATION_GUIDE.md", "quote": "Post-construction cleaning requires a sequential three-phase approach to capture settling airborne drywall gypsum and sawdust: 1. **Phase 1: Rough Debris Pass:** Removal of construction packaging, protective films, tape residue, and rough floor sweeping with HEPA capture. 2. **Phase 2: High-to-Low HEPA Vacuuming:** Dry particle extraction starting from ceiling joists, HVAC diffusers, door casings, down to baseboards. 3. **Phase 3: Wet Microfiber Sparkle Pass:** Multi-bucket damp wipe using electrostatic microfiber cloths to capture remaining microscopic dust films."}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-PST-001",
    "category": "Post-Construction Services",
    "question": "Why does post-construction cleaning require multiple passes?",
    "answer": "Drywall and sawdust particles remain suspended in the air for up to 48 hours after construction wraps up. We utilize certified 0.3-micron HEPA vacuums and a structured three-phase process (rough pass, deep vacuum, damp microfiber sparkle wipe) to prevent settling dust from coating surfaces after cleaning.",
    "escalate_to_human": false
}"}]

[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-SCP-004",
    "category": "Scope of Services",
    "question": "Is there anything you won't clean?",
    "answer": "We do not handle biohazards, mold remediation, or asbestos and lead abatement, and we don't move furniture over 50 lb. We also do not use acid on unsealed natural stone.",
    "escalate_to_human": false
}"}, {"source": "faq_support_knowledgebase.json", "quote": "{
