[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-CAN-005",
    "category": "Booking & Cancellations",
    "question": "What if bad weather stops the technicians from arriving?",
    "answer": "If unsafe travel conditions or a documented emergency prevent service, we reschedule at no charge.",
    "escalate_to_human": false
}"}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-CAN-002",
    "category": "Booking & Cancellations",
    "question": "What is a lockout and what does it cost?",
    "answer": "A lockout means we can't enter within 20 minutes of the start of the arrival window, for example because of a wrong code or a missing key. It is billed at 100% of the scheduled service fee.",
    "escalate_to_human": true
}"}, {"source": "PROPERTY_ACCESS_AND_CANCELLATION_POLICY.md", "quote": "* **Digital Keypads & Smart Locks:** Preferred access method. Clients provide a unique service PIN designated exclusively for Kettle & Loom staff. We recommend a PIN that is active only during the service window. * **Physical Lockboxes:** If using physical keys, keys must remain inside a secure on-site lockbox. Technicians will not carry permanent property keys off-site. Lockbox codes are shared only with the assigned team and changed on request. * **Alarm Systems:** Alarm disarm codes and re-arming instructions must be stored in encrypted client profiles. Any false alarm dispatch fees resulting from inaccurate client codes are the client's responsibility. - Technicians disarm on arrival and re-arm on departure. If an alarm triggers, the technician calls the client and the alarm company within **5 minutes** and gives the correct passcode. - Provide your alarm company's name and the verbal passcode for dispatch. * **Departure Procedure:** Technicians re-lock all doors, close windows, set the thermostat to its original setting, turn off lights, and text a completion notice. * **Key Custody:** Access details are visible only to the Operations team and the assigned technicians. Access codes are removed from the technician's device when the contract ends. * **Garage and Gate Codes:** Provide any gate, garage, or elevator access in your profile."}, {"source": "service_scope_matrix.json", "quote": "scope_matrix_metadata:
{
    "company": "Kettle & Loom Cleaning Collective",
    "standard_version": "3.1",
    "currency": "USD",
    "base_hourly_rate_per_tech": 55.0,
    "labor_estimate_basis": "Technician minutes per 1,000 sq ft of conditioned space for one technician. Divide by team size for on-site duration.",
    "initial_deep_clean_multiplier": {
        "min": 2.0,
        "max": 2.5
    },
    "temperature_notes": {
        "dilution_water_f": "60-80",
        "dilution_water_c": "16-27",
        "chemical_storage_f": "50-80",
        "chemical_storage_c": "10-27"
    }
}"}]

