[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-ACC-002",
    "category": "Property Access & Security",
    "question": "How do you handle my keys and door codes?",
    "answer": "A smart lock with a unique service PIN is preferred. If you use physical keys, they stay in an on-site lockbox, and technicians never carry permanent property keys off-site. Alarm and access codes are stored in encrypted profiles.",
    "escalate_to_human": false
}"}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-ACC-001",
    "category": "Property Access & Security",
    "question": "Do I need to be home when the cleaning collective arrives?",
    "answer": "No. Most residential and commercial clients provide a smart lock code or lockbox key. Our technicians arrive within the designated arrival window, complete the service scope, re-secure all windows and doors, and set the security alarm upon departure.",
    "escalate_to_human": false
}"}, {"source": "PROPERTY_ACCESS_AND_CANCELLATION_POLICY.md", "quote": "* **Digital Keypads & Smart Locks:** Preferred access method. Clients provide a unique service PIN designated exclusively for Kettle & Loom staff. We recommend a PIN that is active only during the service window. * **Physical Lockboxes:** If using physical keys, keys must remain inside a secure on-site lockbox. Technicians will not carry permanent property keys off-site. Lockbox codes are shared only with the assigned team and changed on request. * **Alarm Systems:** Alarm disarm codes and re-arming instructions must be stored in encrypted client profiles. Any false alarm dispatch fees resulting from inaccurate client codes are the client's responsibility. - Technicians disarm on arrival and re-arm on departure. If an alarm triggers, the technician calls the client and the alarm company within **5 minutes** and gives the correct passcode. - Provide your alarm company's name and the verbal passcode for dispatch. * **Departure Procedure:** Technicians re-lock all doors, close windows, set the thermostat to its original setting, turn off lights, and text a completion notice. * **Key Custody:** Access details are visible only to the Operations team and the assigned technicians. Access codes are removed from the technician's device when the contract ends. * **Garage and Gate Codes:** Provide any gate, garage, or elevator access in your profile."}, {"source": "PROPERTY_ACCESS_AND_CANCELLATION_POLICY.md", "quote": "A lockout occurs when technicians cannot enter the property within **20 minutes** of the start of the arrival window because of an incorrect code, a missing key, a deactivated PIN, or a locked interior door. - The technician tries the client's contact numbers and waits up to 20 minutes. - If entry is still not possible, the visit is recorded as a lockout and billed at **100% of the scheduled service fee**. - A one-time free rebooking is not offered for lockouts, but we are glad to help get the next visit set up. - Lockouts due to a building-management error are reviewed on a case-by-case basis."}]

[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-SCP-004",
    "category": "Scope of Services",
    "question": "Is there anything you won't clean?",
    "answer": "We do not handle biohazards, mold remediation, or asbestos and lead abatement, and we don't move furniture over 50 lb. We also do not use acid on unsealed natural stone.",
    "escalate_to_human": false
}"}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-SCP-001",
    "category": "Scope of Services",
    "question": "Do you clean unsealed marble or antique wood furniture?",
