[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-DIAG-004",
    "category": "Diagnostics & Estimates",
    "question": "What happens if you find more problems after taking my car apart?",
    "answer": "Work stops immediately and we send a supplement estimate by SMS with photos. You must approve it separately before we continue. The final bill will not exceed the authorized total by more than 10% or $50.00, whichever is less, without a new approval.",
    "escalate_to_human": false
}"}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-APPT-003",
    "category": "Appointments & Loaners",
    "question": "Can I drop my car off when you are closed?",
    "answer": "Yes. Park in a designated stall, fill out a work order envelope with your name, phone, odometer reading, and a description of the problem, and put the key in the night drop safe at Bay 1. We log your car in the next morning at 6:30 AM, and a service advisor texts you.",
    "escalate_to_human": false
}"}, {"source": "ESTIMATE_AND_AUTHORIZATION_POLICY.md", "quote": "1. The service advisor sends the estimate by SMS (secure link) and email, listing each line item with parts, labor hours, tax, and the total. 2. The customer opens the link and sees the DVI photos and notes for each item. 3. The customer **approves or declines each line item individually**, then signs digitally. 4. The system timestamps the approval and sends a confirmation message with the authorized total. 5. If we haven't heard from you in **2 hours**, we call. We never begin work on silence. 6. Customers without a smartphone can approve in person or by phone with the advisor, and we record the call with consent."}, {"source": "ESTIMATE_AND_AUTHORIZATION_POLICY.md", "quote": "- **No Verbal Guesswork:** Written estimates are delivered via SMS and email with embedded inspection photos. - **Explicit Customer Approval:** No repair work commences without digital or physical written signature authorization. - **Teardown Supplements:** If hidden mechanical damage is discovered post-disassembly, work stops immediately, and a formal supplement estimate is dispatched."}]

[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-APPT-001",
    "category": "Appointments & Loaners",
    "question": "Do you offer loaner vehicles or shuttle services while my car is being serviced?",
    "answer": "Yes. We offer complimentary local shuttle rides within a 10-mile radius. For repairs exceeding $600 or taking longer than 24 hours, complimentary courtesy loaner cars are available upon reservation request (subject to driver license and insurance verification).",
    "escalate_to_human": false
}"}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-FLT-003",
    "category": "Fleet Services",
    "question": "Can I pre-authorize repairs so my drivers don't wait?",
    "answer": "Yes. Fleet managers set a pre-authorized repair limit per vehicle, per visit. The standard limit is $350.00, and it can be raised in writing for approved accounts. Repairs over the limit need written authorization.",
    "escalate_to_human": false
}"}, {"source": "FLEET_SERVICE_SOP.md", "quote": "Fleet vehicles are placed ahead of retail customers in the bay queue, with safety-critical repairs and customer emergencies taking precedence over both. | Service Class | Examples | Guaranteed Turnaround | | :--- | :--- | :--- | | **Preventative Maintenance (PM Tier 1)** | Oil and filter, tire rotation, DVI | **Same-day (under 4 hours)** for drop-offs before **08:30 AM** | | **Minor Mechanical Repairs** | Brakes, alternators, starters | **24-hour** turnaround window | | **Major Drivetrain Overhauls** | Transmission, engine, differential | Dedicated bay allocation with **daily status progress dispatch** | *Table Summary:* [1. Priority Triage & Guaranteed Turnaround (SLA)] - Service Class: Preventative Maintenance (PM Tier 1) | Examples: Oil and filter, tire rotation, DVI | Guaranteed Turnaround: Same-day (under 4 hours) for drop-offs before 08:30 AM - Service Class: Minor Mechanical Repairs | Examples: Brakes, alternators, starters | Guaranteed Turnaround: 24-hour turnaround window - Service Class: Major Drivetrain Overhauls | Examples: Transmission, engine, differential | Guaranteed Turnaround: Dedicated bay allocation with daily status progress dispatch - **Clock Start:** The SLA clock starts when the vehicle is logged into our shop management software, and when diagnostic approval is received if the repair requires authorization above the pre-authorized limit. - **Parts Delays:** If a part is not available locally, we source it from a second supplier. We notify the fleet manager within **2 hours** of discovering a delay, with the new estimated completion time. - **SLA Exceptions:** Delays caused by awaiting approval, hidden damage found during teardown (see `ESTIMATE_AND_AUTHORIZATION_POLICY.md`), or manufacturer back-orders pause the SLA clock. - **Severe-Duty Notice:** Vehicles with GVWR above 14,000 lb are outside the light-fleet scope. Call us to discuss them."}, {"source": "WARRANTY_AND_REPAIR_POLICY.md", "quote": "NorthStar carries garage liability insurance. Report any damage that occurred while your vehicle was in our care **before leaving the lot**, or within 24 hours, and we will investigate."}]

