[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-WAR-002",
    "category": "Warranty & Guarantees",
    "question": "A part you replaced failed while I'm traveling. What should I do?",
    "answer": "Call us or the nationwide warranty hotline before authorizing any repair, and have your invoice number ready. If you are at a participating facility, they diagnose the failure, and a covered repair costs you $0 for parts and labor.",
    "escalate_to_human": true
}"}, {"source": "WARRANTY_AND_REPAIR_POLICY.md", "quote": "| Covered | Not Covered | | :--- | :--- | | A water pump we replaced starts leaking at 14 months | Brake pads worn thin after 18,000 miles of normal driving | | A caliper seal leaks within warranty | Wiper blades that streak | | A starter we installed fails because of a defective part | A repair on a part you supplied | | A serpentine belt tensioner we installed was misinstalled | Failure caused by skipping oil changes or ignoring a DVI RED item | | A loose connection from our labor | Damage from racing, off-road use, or collision | *Table Summary:* [Clear Examples] - Covered: A water pump we replaced starts leaking at 14 months | Not Covered: Brake pads worn thin after 18,000 miles of normal driving - Covered: A caliper seal leaks within warranty | Not Covered: Wiper blades that streak - Covered: A starter we installed fails because of a defective part | Not Covered: A repair on a part you supplied - Covered: A serpentine belt tensioner we installed was misinstalled | Not Covered: Failure caused by skipping oil changes or ignoring a DVI RED item - Covered: A loose connection from our labor | Not Covered: Damage from racing, off-road use, or collision"}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-WAR-005",
    "category": "Warranty & Guarantees",
    "question": "Do I need to keep service records to keep my warranty valid?",
    "answer": "Yes. Keep your invoice and records of routine fluid maintenance such as oil and coolant changes. A failure caused by skipped routine maintenance is excluded.",
    "escalate_to_human": false
}"}, {"source": "WARRANTY_AND_REPAIR_POLICY.md", "quote": "1. Stop driving the vehicle if the problem is a safety issue (brakes, steering, overheating). 2. Call NorthStar or the nationwide warranty hotline with your original invoice number. 3. Bring the vehicle to NorthStar or a participating facility. A technician will diagnose the failure. If it is covered, you pay $0 for parts and labor. 4. Keep your invoice and the maintenance records for your vehicle, because the warranty requires evidence of routine fluid maintenance. If we need to diagnose a failure that turns out not to be covered, the diagnostic fee applies (see Section 3)."}]

[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-FLT-004",
    "category": "Fleet Services",
    "question": "What are your billing terms for commercial accounts?",
    "answer": "Net-30 invoicing after a credit review. Consolidated monthly statements are itemized by VIN and your internal fleet unit ID, and issue on the first business day of each month.",
    "escalate_to_human": true
}"}, {"source": "FLEET_SERVICE_SOP.md", "quote": "- **Terms:** Net-30 invoicing upon credit review approval. Credit review takes up to 3 business days. - **Consolidated Monthly Statements:** Itemized billing grouped by vehicle VIN and internal company fleet unit ID. Statements issue on the **1st business day** of each month for the previous month's work, due 30 days from the statement date. - **Late Balances:** Accounts more than 15 days past due may lose priority scheduling until the account is current. A 1.5% monthly finance charge applies after 30 days. - **Disputes:** Raise invoice questions within 14 days of the statement date. - **Warranty:** Fleet repairs receive the same 24-month/24,000-mile warranty as retail repairs, subject to the severe-duty exclusions in `WARRANTY_AND_REPAIR_POLICY.md`."}, {"source": "FLEET_SERVICE_SOP.md", "quote": "Each fleet account receives a scheduled PM calendar built on `service_intervals_matrix.json`, with reminders sent **14 days** before a unit is due. Units that go more than 1,000 miles past due are flagged on the monthly statement."}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-DIAG-004",
    "category": "Diagnostics & Estimates",
    "question": "What happens if you find more problems after taking my car apart?",
    "answer": "Work stops immediately and we send a supplement estimate by SMS with photos. You must approve it separately before we continue. The final bill will not exceed the authorized total by more than 10% or $50.00, whichever is less, without a new approval.",
    "escalate_to_human": false
}"}]

[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-DIAG-004",
    "category": "Diagnostics & Estimates",
    "question": "What happens if you find more problems after taking my car apart?",
    "answer": "Work stops immediately and we send a supplement estimate by SMS with photos. You must approve it separately before we continue. The final bill will not exceed the authorized total by more than 10% or $50.00, whichever is less, without a new approval.",
    "escalate_to_human": false
}"}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-DIAG-006",
    "category": "Diagnostics & Estimates",
    "question": "Can I keep the parts you replace?",
    "answer": "Yes. Ask when you authorize the work and we'll bag and tag them. Exchange items with a core charge, like alternators and starters, can be inspected on-site, but they must be returned to the distributor.",
    "escalate_to_human": false
}"}, {"source": "service_intervals_matrix.json", "quote": "{
    "service": "Diagnostic (OBD-II scan, circuit test, up to 1 hour teardown analysis)",
    "labor_hours": 1.0,
    "flat_fee": 145.0
}"}, {"source": "ESTIMATE_AND_AUTHORIZATION_POLICY.md", "quote": "Under state automotive repair regulations, customers retain the right to inspect and keep all replaced mechanical parts (excluding exchange items subject to manufacturer core charges, which may be inspected on-site before return to distributor). - Ask for your old parts when you authorize the work, and we will bag and tag them at the front desk. - Core-charge items (alternators, starters, brake calipers, and batteries) can be viewed on-site, but must go back to the distributor. Core charges are listed on the estimate. - Parts that are hazardous (batteries, fluids) will be handed over in sealed containers or disposed of in compliance with the rules. - Unclaimed parts are kept for **7 days** after pickup of the vehicle."}]

