[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-WAR-002",
    "category": "Warranty & Guarantees",
    "question": "A part you replaced failed while I'm traveling. What should I do?",
    "answer": "Call us or the nationwide warranty hotline before authorizing any repair, and have your invoice number ready. If you are at a participating facility, they diagnose the failure, and a covered repair costs you $0 for parts and labor.",
    "escalate_to_human": true
}"}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-DIAG-006",
    "category": "Diagnostics & Estimates",
    "question": "Can I keep the parts you replace?",
    "answer": "Yes. Ask when you authorize the work and we'll bag and tag them. Exchange items with a core charge, like alternators and starters, can be inspected on-site, but they must be returned to the distributor.",
    "escalate_to_human": false
}"}, {"source": "service_intervals_matrix.json", "quote": "{
    "service": "Alternator replacement",
    "labor_hours": 1.8
}"}, {"source": "WARRANTY_AND_REPAIR_POLICY.md", "quote": "1. Stop driving the vehicle if the problem is a safety issue (brakes, steering, overheating). 2. Call NorthStar or the nationwide warranty hotline with your original invoice number. 3. Bring the vehicle to NorthStar or a participating facility. A technician will diagnose the failure. If it is covered, you pay $0 for parts and labor. 4. Keep your invoice and the maintenance records for your vehicle, because the warranty requires evidence of routine fluid maintenance. If we need to diagnose a failure that turns out not to be covered, the diagnostic fee applies (see Section 3)."}]

[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-MNT-005",
    "category": "Routine Maintenance",
    "question": "How much tread do my tires need in winter?",
    "answer": "At least 4/32 inch for snow traction, even though the legal minimum is 2/32 inch. All-season rubber also hardens below 45\u00b0F (7\u00b0C), so dedicated winter tires are recommended for sub-freezing driving.",
    "escalate_to_human": false
}"}, {"source": "service_intervals_matrix.json", "quote": "{
    "service": "Tire mount, balance, and install (set of 4)",
    "labor_hours": 1.2
}"}, {"source": "WINTERIZATION_AND_PREVENTATIVE_GUIDE.md", "quote": "- **Winter Tread Minimum:** All-season tires require a minimum of **4/32 inch** tread depth for snow traction (replacing normal 2/32 inch legal limit). - **How to Check:** Insert a quarter upside down with Washington's head into the groove. If the top of his head is visible, you are below 4/32 inch. We measure all four tires with a depth gauge during the DVI. - **Compound Glass Transition:** All-season rubber compounds harden below 45°F (7°C), significantly increasing braking distances. Dedicated winter tires recommended for sub-freezing regional travel. - **Winter Tires:** Look for the three-peak mountain snowflake symbol. Install a full set of four, and never just two. - **Tire Pressure:** Pressure drops about **1 psi for every 10°F (5.5°C)** drop in temperature. Check monthly with the tires cold, and set to the pressure on the driver-door placard."}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-FLT-005",
    "category": "Fleet Services",
    "question": "Do you service heavy-duty trucks?",
    "answer": "We service commercial light fleets, such as vans and light trucks. Vehicles above 14,000 lb GVWR are outside our standard scope, so please call us to discuss your unit.",
    "escalate_to_human": true
}"}]

