[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-APPT-004",
    "category": "Appointments & Loaners",
    "question": "My car was damaged while at your shop. What do I do?",
    "answer": "Please tell us right away, ideally before leaving the lot, or within 24 hours, and bring photos. A manager reviews every damage report and will contact you.",
    "escalate_to_human": true
}"}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-DIAG-004",
    "category": "Diagnostics & Estimates",
    "question": "What happens if you find more problems after taking my car apart?",
    "answer": "Work stops immediately and we send a supplement estimate by SMS with photos. You must approve it separately before we continue. The final bill will not exceed the authorized total by more than 10% or $50.00, whichever is less, without a new approval.",
    "escalate_to_human": false
}"}, {"source": "ESTIMATE_AND_AUTHORIZATION_POLICY.md", "quote": "Under state automotive repair regulations, customers retain the right to inspect and keep all replaced mechanical parts (excluding exchange items subject to manufacturer core charges, which may be inspected on-site before return to distributor). - Ask for your old parts when you authorize the work, and we will bag and tag them at the front desk. - Core-charge items (alternators, starters, brake calipers, and batteries) can be viewed on-site, but must go back to the distributor. Core charges are listed on the estimate. - Parts that are hazardous (batteries, fluids) will be handed over in sealed containers or disposed of in compliance with the rules. - Unclaimed parts are kept for **7 days** after pickup of the vehicle."}, {"source": "WARRANTY_AND_REPAIR_POLICY.md", "quote": "NorthStar carries garage liability insurance. Report any damage that occurred while your vehicle was in our care **before leaving the lot**, or within 24 hours, and we will investigate."}]

