[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-DIAG-004",
    "category": "Diagnostics & Estimates",
    "question": "What happens if you find more problems after taking my car apart?",
    "answer": "Work stops immediately and we send a supplement estimate by SMS with photos. You must approve it separately before we continue. The final bill will not exceed the authorized total by more than 10% or $50.00, whichever is less, without a new approval.",
    "escalate_to_human": false
}"}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-FLT-004",
    "category": "Fleet Services",
    "question": "What are your billing terms for commercial accounts?",
    "answer": "Net-30 invoicing after a credit review. Consolidated monthly statements are itemized by VIN and your internal fleet unit ID, and issue on the first business day of each month.",
    "escalate_to_human": true
}"}, {"source": "ESTIMATE_AND_AUTHORIZATION_POLICY.md", "quote": "1. The service advisor sends the estimate by SMS (secure link) and email, listing each line item with parts, labor hours, tax, and the total. 2. The customer opens the link and sees the DVI photos and notes for each item. 3. The customer **approves or declines each line item individually**, then signs digitally. 4. The system timestamps the approval and sends a confirmation message with the authorized total. 5. If we haven't heard from you in **2 hours**, we call. We never begin work on silence. 6. Customers without a smartphone can approve in person or by phone with the advisor, and we record the call with consent."}, {"source": "ESTIMATE_AND_AUTHORIZATION_POLICY.md", "quote": "- If more work is found, the technician stops, photographs the issue, and the advisor sends a **supplement estimate** by SMS. - Supplements follow the same approval workflow, and the original authorization does not cover them. - If the supplement is declined, we reassemble the vehicle. Teardown and reassembly labor already performed is billed at the quoted rate, and we explain it before starting. - **Price Variance Rule:** The final bill won't exceed the authorized total by more than 10% or $50.00 (whichever is less) without a new written approval."}]

[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-APPT-004",
    "category": "Appointments & Loaners",
    "question": "My car was damaged while at your shop. What do I do?",
    "answer": "Please tell us right away, ideally before leaving the lot, or within 24 hours, and bring photos. A manager reviews every damage report and will contact you.",
    "escalate_to_human": true
}"}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-WAR-002",
    "category": "Warranty & Guarantees",
    "question": "A part you replaced failed while I'm traveling. What should I do?",
    "answer": "Call us or the nationwide warranty hotline before authorizing any repair, and have your invoice number ready. If you are at a participating facility, they diagnose the failure, and a covered repair costs you $0 for parts and labor.",
    "escalate_to_human": true
}"}, {"source": "WINTERIZATION_AND_PREVENTATIVE_GUIDE.md", "quote": "- **Wash:** Rinse the vehicle every **10 to 14 days** during salt season, and after any storm, particularly the undercarriage, wheel wells, and rocker panels. Wash when temperatures are above 32°F (0°C) so the doors and locks don't freeze. - **Inspect:** Brake lines, fuel lines, and suspension components rust first. These are checked in the DVI. - **Protect:** Undercoating or wax-based rust inhibitors in the fall protect exposed metal, and a coat of wax on the paint protects the finish. - **Dry:** Lubricate door seals with silicone spray to prevent freezing. Wipe door jambs. - **Brake Components:** Salt corrodes calipers and slide pins, so we clean and lubricate them at each brake service."}, {"source": "ESTIMATE_AND_AUTHORIZATION_POLICY.md", "quote": "Under state automotive repair regulations, customers retain the right to inspect and keep all replaced mechanical parts (excluding exchange items subject to manufacturer core charges, which may be inspected on-site before return to distributor). - Ask for your old parts when you authorize the work, and we will bag and tag them at the front desk. - Core-charge items (alternators, starters, brake calipers, and batteries) can be viewed on-site, but must go back to the distributor. Core charges are listed on the estimate. - Parts that are hazardous (batteries, fluids) will be handed over in sealed containers or disposed of in compliance with the rules. - Unclaimed parts are kept for **7 days** after pickup of the vehicle."}]

[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-APPT-001",
    "category": "Appointments & Loaners",
    "question": "Do you offer loaner vehicles or shuttle services while my car is being serviced?",
    "answer": "Yes. We offer complimentary local shuttle rides within a 10-mile radius. For repairs exceeding $600 or taking longer than 24 hours, complimentary courtesy loaner cars are available upon reservation request (subject to driver license and insurance verification).",
    "escalate_to_human": false
}"}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-WAR-004",
    "category": "Warranty & Guarantees",
    "question": "Does the warranty cover towing or a rental car?",
    "answer": "No. The warranty covers the repaired part and labor, and not towing, rentals, lost time, or consequential damage, except where state law requires otherwise.",
    "escalate_to_human": false
}"}, {"source": "WARRANTY_AND_REPAIR_POLICY.md", "quote": "- Parts are warranted at the level of the manufacturer or longer. If the manufacturer's warranty is shorter than 24 months, NorthStar covers the remainder of our 24 months or 24,000 miles. - **Consequential Damage:** Towing, rental cars, lost time, and secondary damage are not covered, except where required by law. - Where state law gives you greater rights, the law applies."}, {"source": "ESTIMATE_AND_AUTHORIZATION_POLICY.md", "quote": "Under state automotive repair regulations, customers retain the right to inspect and keep all replaced mechanical parts (excluding exchange items subject to manufacturer core charges, which may be inspected on-site before return to distributor). - Ask for your old parts when you authorize the work, and we will bag and tag them at the front desk. - Core-charge items (alternators, starters, brake calipers, and batteries) can be viewed on-site, but must go back to the distributor. Core charges are listed on the estimate. - Parts that are hazardous (batteries, fluids) will be handed over in sealed containers or disposed of in compliance with the rules. - Unclaimed parts are kept for **7 days** after pickup of the vehicle."}]

