[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-APPT-004",
    "category": "Appointments & Loaners",
    "question": "My car was damaged while at your shop. What do I do?",
    "answer": "Please tell us right away, ideally before leaving the lot, or within 24 hours, and bring photos. A manager reviews every damage report and will contact you.",
    "escalate_to_human": true
}"}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-DIAG-006",
    "category": "Diagnostics & Estimates",
    "question": "Can I keep the parts you replace?",
    "answer": "Yes. Ask when you authorize the work and we'll bag and tag them. Exchange items with a core charge, like alternators and starters, can be inspected on-site, but they must be returned to the distributor.",
    "escalate_to_human": false
}"}, {"source": "WINTERIZATION_AND_PREVENTATIVE_GUIDE.md", "quote": "- **Wash:** Rinse the vehicle every **10 to 14 days** during salt season, and after any storm, particularly the undercarriage, wheel wells, and rocker panels. Wash when temperatures are above 32°F (0°C) so the doors and locks don't freeze. - **Inspect:** Brake lines, fuel lines, and suspension components rust first. These are checked in the DVI. - **Protect:** Undercoating or wax-based rust inhibitors in the fall protect exposed metal, and a coat of wax on the paint protects the finish. - **Dry:** Lubricate door seals with silicone spray to prevent freezing. Wipe door jambs. - **Brake Components:** Salt corrodes calipers and slide pins, so we clean and lubricate them at each brake service."}, {"source": "ESTIMATE_AND_AUTHORIZATION_POLICY.md", "quote": "Under state automotive repair regulations, customers retain the right to inspect and keep all replaced mechanical parts (excluding exchange items subject to manufacturer core charges, which may be inspected on-site before return to distributor). - Ask for your old parts when you authorize the work, and we will bag and tag them at the front desk. - Core-charge items (alternators, starters, brake calipers, and batteries) can be viewed on-site, but must go back to the distributor. Core charges are listed on the estimate. - Parts that are hazardous (batteries, fluids) will be handed over in sealed containers or disposed of in compliance with the rules. - Unclaimed parts are kept for **7 days** after pickup of the vehicle."}]

[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-WAR-004",
    "category": "Warranty & Guarantees",
    "question": "Does the warranty cover towing or a rental car?",
    "answer": "No. The warranty covers the repaired part and labor, and not towing, rentals, lost time, or consequential damage, except where state law requires otherwise.",
    "escalate_to_human": false
}"}, {"source": "WARRANTY_AND_REPAIR_POLICY.md", "quote": "- Parts are warranted at the level of the manufacturer or longer. If the manufacturer's warranty is shorter than 24 months, NorthStar covers the remainder of our 24 months or 24,000 miles. - **Consequential Damage:** Towing, rental cars, lost time, and secondary damage are not covered, except where required by law. - Where state law gives you greater rights, the law applies."}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-DIAG-006",
    "category": "Diagnostics & Estimates",
    "question": "Can I keep the parts you replace?",
    "answer": "Yes. Ask when you authorize the work and we'll bag and tag them. Exchange items with a core charge, like alternators and starters, can be inspected on-site, but they must be returned to the distributor.",
    "escalate_to_human": false
}"}, {"source": "FLEET_SERVICE_SOP.md", "quote": "- **Terms:** Net-30 invoicing upon credit review approval. Credit review takes up to 3 business days. - **Consolidated Monthly Statements:** Itemized billing grouped by vehicle VIN and internal company fleet unit ID. Statements issue on the **1st business day** of each month for the previous month's work, due 30 days from the statement date. - **Late Balances:** Accounts more than 15 days past due may lose priority scheduling until the account is current. A 1.5% monthly finance charge applies after 30 days. - **Disputes:** Raise invoice questions within 14 days of the statement date. - **Warranty:** Fleet repairs receive the same 24-month/24,000-mile warranty as retail repairs, subject to the severe-duty exclusions in `WARRANTY_AND_REPAIR_POLICY.md`."}]

[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-DIAG-006",
    "category": "Diagnostics & Estimates",
    "question": "Can I keep the parts you replace?",
    "answer": "Yes. Ask when you authorize the work and we'll bag and tag them. Exchange items with a core charge, like alternators and starters, can be inspected on-site, but they must be returned to the distributor.",
    "escalate_to_human": false
}"}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-MNT-001",
    "category": "Routine Maintenance",
    "question": "How often should I change my oil?",
    "answer": "Every 5,000 miles or 6 months with a full synthetic oil that meets API SP / ILSAC GF-6 (0W-20 or 5W-30, per your owner's manual). Our Tier 1 service includes the oil and OEM filter, a tire rotation, a brake measurement, and a 40-point inspection for $89.95.",
    "escalate_to_human": false
}"}, {"source": "FLEET_SERVICE_SOP.md", "quote": "1. Secure vehicle in designated Fleet North Lot parking stalls. 2. Complete the Fleet Work Order envelope detailing unit ID, current odometer, and primary driver complaint. 3. Deposit key into the tamper-evident dual-locking night drop safe located at the Bay 1 exterior wall. 4. Early shift dispatch technician logs intake scans into shop management software at **06:30 AM**. **Notes** - Lock the vehicle and remove valuables, fuel cards, and tools. - Any vehicle dropped after-hours is treated as received at 06:30 AM for SLA purposes. It does not qualify for the 08:30 AM same-day PM guarantee unless it was in the lot before 08:30 AM and logged by 06:30 AM, which is the standard case. - NorthStar is not responsible for items left in vehicles. - Our lot is lit and under camera surveillance."}, {"source": "ESTIMATE_AND_AUTHORIZATION_POLICY.md", "quote": "Under state automotive repair regulations, customers retain the right to inspect and keep all replaced mechanical parts (excluding exchange items subject to manufacturer core charges, which may be inspected on-site before return to distributor). - Ask for your old parts when you authorize the work, and we will bag and tag them at the front desk. - Core-charge items (alternators, starters, brake calipers, and batteries) can be viewed on-site, but must go back to the distributor. Core charges are listed on the estimate. - Parts that are hazardous (batteries, fluids) will be handed over in sealed containers or disposed of in compliance with the rules. - Unclaimed parts are kept for **7 days** after pickup of the vehicle."}]

