[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-DIAG-006",
    "category": "Diagnostics & Estimates",
    "question": "Can I keep the parts you replace?",
    "answer": "Yes. Ask when you authorize the work and we'll bag and tag them. Exchange items with a core charge, like alternators and starters, can be inspected on-site, but they must be returned to the distributor.",
    "escalate_to_human": false
}"}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-DIAG-004",
    "category": "Diagnostics & Estimates",
    "question": "What happens if you find more problems after taking my car apart?",
    "answer": "Work stops immediately and we send a supplement estimate by SMS with photos. You must approve it separately before we continue. The final bill will not exceed the authorized total by more than 10% or $50.00, whichever is less, without a new approval.",
    "escalate_to_human": false
}"}, {"source": "ESTIMATE_AND_AUTHORIZATION_POLICY.md", "quote": "- If more work is found, the technician stops, photographs the issue, and the advisor sends a **supplement estimate** by SMS. - Supplements follow the same approval workflow, and the original authorization does not cover them. - If the supplement is declined, we reassemble the vehicle. Teardown and reassembly labor already performed is billed at the quoted rate, and we explain it before starting. - **Price Variance Rule:** The final bill won't exceed the authorized total by more than 10% or $50.00 (whichever is less) without a new written approval."}, {"source": "ESTIMATE_AND_AUTHORIZATION_POLICY.md", "quote": "Under state automotive repair regulations, customers retain the right to inspect and keep all replaced mechanical parts (excluding exchange items subject to manufacturer core charges, which may be inspected on-site before return to distributor). - Ask for your old parts when you authorize the work, and we will bag and tag them at the front desk. - Core-charge items (alternators, starters, brake calipers, and batteries) can be viewed on-site, but must go back to the distributor. Core charges are listed on the estimate. - Parts that are hazardous (batteries, fluids) will be handed over in sealed containers or disposed of in compliance with the rules. - Unclaimed parts are kept for **7 days** after pickup of the vehicle."}]

[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-FLT-001",
    "category": "Fleet Services",
    "question": "How do after-hours drop-offs work for commercial fleet vehicles?",
    "answer": "Park your vehicle in our secure Fleet North Lot stalls, complete the Fleet Work Order envelope with your fleet unit number, odometer, and driver notes, and place the key in the tamper-evident dual-locking drop safe at the Bay 1 exterior wall. Our early-shift dispatch team logs all vehicles at 6:30 AM for priority triage.",
    "escalate_to_human": false
}"}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-FLT-005",
    "category": "Fleet Services",
    "question": "Do you service heavy-duty trucks?",
    "answer": "We service commercial light fleets, such as vans and light trucks. Vehicles above 14,000 lb GVWR are outside our standard scope, so please call us to discuss your unit.",
    "escalate_to_human": true
}"}, {"source": "FLEET_SERVICE_SOP.md", "quote": "1. Secure vehicle in designated Fleet North Lot parking stalls. 2. Complete the Fleet Work Order envelope detailing unit ID, current odometer, and primary driver complaint. 3. Deposit key into the tamper-evident dual-locking night drop safe located at the Bay 1 exterior wall. 4. Early shift dispatch technician logs intake scans into shop management software at **06:30 AM**. **Notes** - Lock the vehicle and remove valuables, fuel cards, and tools. - Any vehicle dropped after-hours is treated as received at 06:30 AM for SLA purposes. It does not qualify for the 08:30 AM same-day PM guarantee unless it was in the lot before 08:30 AM and logged by 06:30 AM, which is the standard case. - NorthStar is not responsible for items left in vehicles. - Our lot is lit and under camera surveillance."}, {"source": "FLEET_SERVICE_SOP.md", "quote": "- Morning dispatch begins at **06:30 AM** with the early-shift dispatch technician logging after-hours drop-offs and arranging the day's bay assignments. - **Priority Order:** (1) Safety-critical (RED) fleet repairs, (2) PM Tier 1 drop-offs received before 08:30 AM, (3) scheduled minor repairs, (4) other fleet work, (5) retail customers. - Fleet managers receive a text and email with a work-order number for each unit by **07:30 AM**. - Fleet DVI reports are issued within **90 minutes** of drop-off, with photos and a color grade for each of the 40 inspection points. - Pickup updates: Units are staged in the Fleet North Lot, and keys are available at the front desk from 7:00 AM."}]

[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-APPT-001",
    "category": "Appointments & Loaners",
    "question": "Do you offer loaner vehicles or shuttle services while my car is being serviced?",
    "answer": "Yes. We offer complimentary local shuttle rides within a 10-mile radius. For repairs exceeding $600 or taking longer than 24 hours, complimentary courtesy loaner cars are available upon reservation request (subject to driver license and insurance verification).",
    "escalate_to_human": false
}"}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-FLT-003",
    "category": "Fleet Services",
    "question": "Can I pre-authorize repairs so my drivers don't wait?",
    "answer": "Yes. Fleet managers set a pre-authorized repair limit per vehicle, per visit. The standard limit is $350.00, and it can be raised in writing for approved accounts. Repairs over the limit need written authorization.",
    "escalate_to_human": false
}"}, {"source": "FLEET_SERVICE_SOP.md", "quote": "- Fleet managers designate a **pre-authorized repair limit (standard: $350.00)** to expedite workflow without waiting for written authorizations. - Repairs at or under the limit proceed immediately after the DVI. They are documented on the invoice. - Repairs **over the limit** need written authorization through the SMS or email approval link from a designated authorized contact. Alternatively, call the fleet desk. - The limit applies **per vehicle, per visit**, not per line item, and cannot be split to avoid authorization. - Limits can be raised in writing, up to $1,000.00 for approved Net-30 accounts, and can be set per unit ID. - Safety-critical RED items are always reported to the fleet manager, even if under the limit."}, {"source": "ESTIMATE_AND_AUTHORIZATION_POLICY.md", "quote": "Under state automotive repair regulations, customers retain the right to inspect and keep all replaced mechanical parts (excluding exchange items subject to manufacturer core charges, which may be inspected on-site before return to distributor). - Ask for your old parts when you authorize the work, and we will bag and tag them at the front desk. - Core-charge items (alternators, starters, brake calipers, and batteries) can be viewed on-site, but must go back to the distributor. Core charges are listed on the estimate. - Parts that are hazardous (batteries, fluids) will be handed over in sealed containers or disposed of in compliance with the rules. - Unclaimed parts are kept for **7 days** after pickup of the vehicle."}]

[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-APPT-004",
    "category": "Appointments & Loaners",
    "question": "My car was damaged while at your shop. What do I do?",
    "answer": "Please tell us right away, ideally before leaving the lot, or within 24 hours, and bring photos. A manager reviews every damage report and will contact you.",
    "escalate_to_human": true
}"}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-APPT-003",
    "category": "Appointments & Loaners",
    "question": "Can I drop my car off when you are closed?",
    "answer": "Yes. Park in a designated stall, fill out a work order envelope with your name, phone, odometer reading, and a description of the problem, and put the key in the night drop safe at Bay 1. We log your car in the next morning at 6:30 AM, and a service advisor texts you.",
    "escalate_to_human": false
}"}, {"source": "WINTERIZATION_AND_PREVENTATIVE_GUIDE.md", "quote": "- **Wash:** Rinse the vehicle every **10 to 14 days** during salt season, and after any storm, particularly the undercarriage, wheel wells, and rocker panels. Wash when temperatures are above 32°F (0°C) so the doors and locks don't freeze. - **Inspect:** Brake lines, fuel lines, and suspension components rust first. These are checked in the DVI. - **Protect:** Undercoating or wax-based rust inhibitors in the fall protect exposed metal, and a coat of wax on the paint protects the finish. - **Dry:** Lubricate door seals with silicone spray to prevent freezing. Wipe door jambs. - **Brake Components:** Salt corrodes calipers and slide pins, so we clean and lubricate them at each brake service."}, {"source": "ESTIMATE_AND_AUTHORIZATION_POLICY.md", "quote": "Under state automotive repair regulations, customers retain the right to inspect and keep all replaced mechanical parts (excluding exchange items subject to manufacturer core charges, which may be inspected on-site before return to distributor). - Ask for your old parts when you authorize the work, and we will bag and tag them at the front desk. - Core-charge items (alternators, starters, brake calipers, and batteries) can be viewed on-site, but must go back to the distributor. Core charges are listed on the estimate. - Parts that are hazardous (batteries, fluids) will be handed over in sealed containers or disposed of in compliance with the rules. - Unclaimed parts are kept for **7 days** after pickup of the vehicle."}]

