[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-DIAG-004",
    "category": "Diagnostics & Estimates",
    "question": "What happens if you find more problems after taking my car apart?",
    "answer": "Work stops immediately and we send a supplement estimate by SMS with photos. You must approve it separately before we continue. The final bill will not exceed the authorized total by more than 10% or $50.00, whichever is less, without a new approval.",
    "escalate_to_human": false
}"}, {"source": "ESTIMATE_AND_AUTHORIZATION_POLICY.md", "quote": "1. The service advisor sends the estimate by SMS (secure link) and email, listing each line item with parts, labor hours, tax, and the total. 2. The customer opens the link and sees the DVI photos and notes for each item. 3. The customer **approves or declines each line item individually**, then signs digitally. 4. The system timestamps the approval and sends a confirmation message with the authorized total. 5. If we haven't heard from you in **2 hours**, we call. We never begin work on silence. 6. Customers without a smartphone can approve in person or by phone with the advisor, and we record the call with consent."}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-DIAG-003",
    "category": "Diagnostics & Estimates",
    "question": "Will you start work before I approve the estimate?",
    "answer": "No. Estimates are sent by SMS and email with inspection photos, and you approve or decline each line item individually. No repair work begins without a digital or written signature.",
    "escalate_to_human": false
}"}, {"source": "ESTIMATE_AND_AUTHORIZATION_POLICY.md", "quote": "- If more work is found, the technician stops, photographs the issue, and the advisor sends a **supplement estimate** by SMS. - Supplements follow the same approval workflow, and the original authorization does not cover them. - If the supplement is declined, we reassemble the vehicle. Teardown and reassembly labor already performed is billed at the quoted rate, and we explain it before starting. - **Price Variance Rule:** The final bill won't exceed the authorized total by more than 10% or $50.00 (whichever is less) without a new written approval."}]

[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-MNT-005",
    "category": "Routine Maintenance",
    "question": "How much tread do my tires need in winter?",
    "answer": "At least 4/32 inch for snow traction, even though the legal minimum is 2/32 inch. All-season rubber also hardens below 45\u00b0F (7\u00b0C), so dedicated winter tires are recommended for sub-freezing driving.",
    "escalate_to_human": false
}"}, {"source": "service_intervals_matrix.json", "quote": "{
    "service": "Tire mount, balance, and install (set of 4)",
    "labor_hours": 1.2
}"}, {"source": "WINTERIZATION_AND_PREVENTATIVE_GUIDE.md", "quote": "- **Winter Tread Minimum:** All-season tires require a minimum of **4/32 inch** tread depth for snow traction (replacing normal 2/32 inch legal limit). - **How to Check:** Insert a quarter upside down with Washington's head into the groove. If the top of his head is visible, you are below 4/32 inch. We measure all four tires with a depth gauge during the DVI. - **Compound Glass Transition:** All-season rubber compounds harden below 45°F (7°C), significantly increasing braking distances. Dedicated winter tires recommended for sub-freezing regional travel. - **Winter Tires:** Look for the three-peak mountain snowflake symbol. Install a full set of four, and never just two. - **Tire Pressure:** Pressure drops about **1 psi for every 10°F (5.5°C)** drop in temperature. Check monthly with the tires cold, and set to the pressure on the driver-door placard."}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-MNT-001",
    "category": "Routine Maintenance",
    "question": "How often should I change my oil?",
    "answer": "Every 5,000 miles or 6 months with a full synthetic oil that meets API SP / ILSAC GF-6 (0W-20 or 5W-30, per your owner's manual). Our Tier 1 service includes the oil and OEM filter, a tire rotation, a brake measurement, and a 40-point inspection for $89.95.",
    "escalate_to_human": false
}"}]

