[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-WAR-001",
    "category": "Warranty & Guarantees",
    "question": "What is covered under the NorthStar Peace of Mind Warranty?",
    "answer": "Our warranty covers parts and labor on qualifying mechanical repairs for 24 months or 24,000 miles, whichever comes first. It is honored at over 35,000 certified facilities nationwide. It excludes customer-supplied parts, routine friction wear (wiper blades, brake pads), commercial severe-duty abuse, racing, and failures from skipped routine fluid maintenance.",
    "escalate_to_human": false
}"}, {"source": "WARRANTY_AND_REPAIR_POLICY.md", "quote": "- Parts are warranted at the level of the manufacturer or longer. If the manufacturer's warranty is shorter than 24 months, NorthStar covers the remainder of our 24 months or 24,000 miles. - **Consequential Damage:** Towing, rental cars, lost time, and secondary damage are not covered, except where required by law. - Where state law gives you greater rights, the law applies."}, {"source": "WARRANTY_AND_REPAIR_POLICY.md", "quote": "NorthStar Auto Care warrants all parts and labor performed by our ASE-certified technicians for **24 months or 24,000 miles**, whichever occurs first. - **Coverage:** Mechanical parts replacement failure, installation labor defects, and hydraulic seal leaks. Both **parts and labor** are covered at no charge for the repaired component. - **Nationwide Protection:** Valid at over 35,000 certified participating repair centers across North America. If you are more than 25 miles from NorthStar, call the warranty hotline before authorizing any repair so the claim can be validated. - **Exclusions:** Commercial severe-duty abuse, auto racing, lack of subsequent routine fluid maintenance, customer-supplied parts, and normal brake pad/wiper friction wear."}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-WAR-004",
    "category": "Warranty & Guarantees",
    "question": "Does the warranty cover towing or a rental car?",
    "answer": "No. The warranty covers the repaired part and labor, and not towing, rentals, lost time, or consequential damage, except where state law requires otherwise.",
    "escalate_to_human": false
}"}]

[{"source": "faq_support_knowledgebase.json", "quote": "{
