[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-DIAG-004",
    "category": "Diagnostics & Estimates",
    "question": "What happens if you find more problems after taking my car apart?",
    "answer": "Work stops immediately and we send a supplement estimate by SMS with photos. You must approve it separately before we continue. The final bill will not exceed the authorized total by more than 10% or $50.00, whichever is less, without a new approval.",
    "escalate_to_human": false
}"}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-DIAG-003",
    "category": "Diagnostics & Estimates",
    "question": "Will you start work before I approve the estimate?",
    "answer": "No. Estimates are sent by SMS and email with inspection photos, and you approve or decline each line item individually. No repair work begins without a digital or written signature.",
    "escalate_to_human": false
}"}, {"source": "ESTIMATE_AND_AUTHORIZATION_POLICY.md", "quote": "1. The service advisor sends the estimate by SMS (secure link) and email, listing each line item with parts, labor hours, tax, and the total. 2. The customer opens the link and sees the DVI photos and notes for each item. 3. The customer **approves or declines each line item individually**, then signs digitally. 4. The system timestamps the approval and sends a confirmation message with the authorized total. 5. If we haven't heard from you in **2 hours**, we call. We never begin work on silence. 6. Customers without a smartphone can approve in person or by phone with the advisor, and we record the call with consent."}, {"source": "FLEET_SERVICE_SOP.md", "quote": "- **Terms:** Net-30 invoicing upon credit review approval. Credit review takes up to 3 business days. - **Consolidated Monthly Statements:** Itemized billing grouped by vehicle VIN and internal company fleet unit ID. Statements issue on the **1st business day** of each month for the previous month's work, due 30 days from the statement date. - **Late Balances:** Accounts more than 15 days past due may lose priority scheduling until the account is current. A 1.5% monthly finance charge applies after 30 days. - **Disputes:** Raise invoice questions within 14 days of the statement date. - **Warranty:** Fleet repairs receive the same 24-month/24,000-mile warranty as retail repairs, subject to the severe-duty exclusions in `WARRANTY_AND_REPAIR_POLICY.md`."}]

[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-FLT-005",
    "category": "Fleet Services",
    "question": "Do you service heavy-duty trucks?",
    "answer": "We service commercial light fleets, such as vans and light trucks. Vehicles above 14,000 lb GVWR are outside our standard scope, so please call us to discuss your unit.",
    "escalate_to_human": true
}"}, {"source": "FLEET_SERVICE_SOP.md", "quote": "Fleet vehicles are placed ahead of retail customers in the bay queue, with safety-critical repairs and customer emergencies taking precedence over both. | Service Class | Examples | Guaranteed Turnaround | | :--- | :--- | :--- | | **Preventative Maintenance (PM Tier 1)** | Oil and filter, tire rotation, DVI | **Same-day (under 4 hours)** for drop-offs before **08:30 AM** | | **Minor Mechanical Repairs** | Brakes, alternators, starters | **24-hour** turnaround window | | **Major Drivetrain Overhauls** | Transmission, engine, differential | Dedicated bay allocation with **daily status progress dispatch** | *Table Summary:* [1. Priority Triage & Guaranteed Turnaround (SLA)] - Service Class: Preventative Maintenance (PM Tier 1) | Examples: Oil and filter, tire rotation, DVI | Guaranteed Turnaround: Same-day (under 4 hours) for drop-offs before 08:30 AM - Service Class: Minor Mechanical Repairs | Examples: Brakes, alternators, starters | Guaranteed Turnaround: 24-hour turnaround window - Service Class: Major Drivetrain Overhauls | Examples: Transmission, engine, differential | Guaranteed Turnaround: Dedicated bay allocation with daily status progress dispatch - **Clock Start:** The SLA clock starts when the vehicle is logged into our shop management software, and when diagnostic approval is received if the repair requires authorization above the pre-authorized limit. - **Parts Delays:** If a part is not available locally, we source it from a second supplier. We notify the fleet manager within **2 hours** of discovering a delay, with the new estimated completion time. - **SLA Exceptions:** Delays caused by awaiting approval, hidden damage found during teardown (see `ESTIMATE_AND_AUTHORIZATION_POLICY.md`), or manufacturer back-orders pause the SLA clock. - **Severe-Duty Notice:** Vehicles with GVWR above 14,000 lb are outside the light-fleet scope. Call us to discuss them."}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-FLT-001",
    "category": "Fleet Services",
    "question": "How do after-hours drop-offs work for commercial fleet vehicles?",
    "answer": "Park your vehicle in our secure Fleet North Lot stalls, complete the Fleet Work Order envelope with your fleet unit number, odometer, and driver notes, and place the key in the tamper-evident dual-locking drop safe at the Bay 1 exterior wall. Our early-shift dispatch team logs all vehicles at 6:30 AM for priority triage.",
    "escalate_to_human": false
}"}]

[{"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-APPT-001",
    "category": "Appointments & Loaners",
    "question": "Do you offer loaner vehicles or shuttle services while my car is being serviced?",
    "answer": "Yes. We offer complimentary local shuttle rides within a 10-mile radius. For repairs exceeding $600 or taking longer than 24 hours, complimentary courtesy loaner cars are available upon reservation request (subject to driver license and insurance verification).",
    "escalate_to_human": false
}"}, {"source": "faq_support_knowledgebase.json", "quote": "{
    "id": "FAQ-FLT-003",
    "category": "Fleet Services",
    "question": "Can I pre-authorize repairs so my drivers don't wait?",
    "answer": "Yes. Fleet managers set a pre-authorized repair limit per vehicle, per visit. The standard limit is $350.00, and it can be raised in writing for approved accounts. Repairs over the limit need written authorization.",
    "escalate_to_human": false
}"}, {"source": "FLEET_SERVICE_SOP.md", "quote": "- Fleet managers designate a **pre-authorized repair limit (standard: $350.00)** to expedite workflow without waiting for written authorizations. - Repairs at or under the limit proceed immediately after the DVI. They are documented on the invoice. - Repairs **over the limit** need written authorization through the SMS or email approval link from a designated authorized contact. Alternatively, call the fleet desk. - The limit applies **per vehicle, per visit**, not per line item, and cannot be split to avoid authorization. - Limits can be raised in writing, up to $1,000.00 for approved Net-30 accounts, and can be set per unit ID. - Safety-critical RED items are always reported to the fleet manager, even if under the limit."}, {"source": "FLEET_SERVICE_SOP.md", "quote": "- **Terms:** Net-30 invoicing upon credit review approval. Credit review takes up to 3 business days. - **Consolidated Monthly Statements:** Itemized billing grouped by vehicle VIN and internal company fleet unit ID. Statements issue on the **1st business day** of each month for the previous month's work, due 30 days from the statement date. - **Late Balances:** Accounts more than 15 days past due may lose priority scheduling until the account is current. A 1.5% monthly finance charge applies after 30 days. - **Disputes:** Raise invoice questions within 14 days of the statement date. - **Warranty:** Fleet repairs receive the same 24-month/24,000-mile warranty as retail repairs, subject to the severe-duty exclusions in `WARRANTY_AND_REPAIR_POLICY.md`."}]

